let lang='ja',S,db,page='home',helpMode=false,undoState=null,overlayCleanup=null,timers=[],recording=null,audioChunks=[],pendingSound=null;
const $=(id)=>document.getElementById(id), esc=(s)=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const t=k=>(I[k]||[k,k,k])[{ja:0,en:1,fr:2}[lang]],L=(a,b,c)=>[a,b||a,c||b||a][{ja:0,en:1,fr:2}[lang]],uid=()=>crypto.randomUUID?crypto.randomUUID():Date.now()+'-'+Math.random().toString(36).slice(2),day=(d=new Date())=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`,localDT=(d=new Date())=>day(d)+'T'+String(d.getHours()).padStart(2,'0')+':'+String(d.getMinutes()).padStart(2,'0');
