const defaults=()=>({schema:1,entries:[],medications:[],plans:[],contacts:Array.from({length:30},()=>({name:'',number:''})),owner:{},frames:[],fortune:{},settings:{lang:'ja',dark:false,large:false,hidden:[],ownerVisible:false},lastBackup:null});
function toast(msg){$('toast').textContent=msg;$('toast').hidden=false;clearTimeout(toast.id);toast.id=setTimeout(()=>$('toast').hidden=true,5500)}
function openDB(){return new Promise((resolve,reject)=>{const q=indexedDB.open('watashiplus-himekoro-v1',1);q.onupgradeneeded=()=>q.result.createObjectStore('data');q.onsuccess=()=>{db=q.result;resolve()};q.onerror=()=>reject(q.error)})}
function readDB(){return new Promise((resolve,reject)=>{const q=db.transaction('data').objectStore('data').get('state');q.onsuccess=()=>resolve(q.result);q.onerror=()=>reject(q.error)})}
function writeDB(value){return new Promise((resolve,reject)=>{const tx=db.transaction('data','readwrite');tx.objectStore('data').put(value,'state');tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error||Error('aborted'))})}
let mutationQueue=Promise.resolve();
function mutate(...args){const task=mutationQueue.then(()=>transact(...args));mutationQueue=task.catch(()=>{});return task}
async function transact(fn,{undo=true,refresh=true}={}){const next=structuredClone(S);try{fn(next);await writeDB(next);S=next;if(refresh)render();return true}catch(e){toast(t('failed'));console.error('Storage error',e.name);return false}}
async function undo(){if(!undoState)return;const previous=undoState;if(await mutate(n=>{Object.keys(n).forEach(k=>delete n[k]);Object.assign(n,previous)},{undo:false})){undoState=null;render();toast(L('取り消しました','Undone','Annulé'))}}
const btn=(label,action,cls='',help='')=>`<button type="button" class="${cls}" data-action="${esc(action)}" data-help="${esc(help||action.split(':')[0])}">${label}</button>`;
let field=(label,id,value='',type='text',attrs='')=>`<label>${esc(label)}<input id="${id}" type="${type}" value="${esc(value)}" ${attrs}></label>`;
const area=(label,id,value='')=>`<label>${esc(label)}<textarea placeholder="タップして入力" id="${id}">${esc(value)}</textarea></label>`;
const select=(label,id,arr,value='')=>`<label>${esc(label)}<select id="${id}">${arr.map(a=>{const v=Array.isArray(a)?a[0]:a,n=Array.isArray(a)?a[1]:a;return `<option value="${esc(v)}" ${v===value?'selected':''}>${esc(n)}</option>`}).join('')}</select></label>`;
const icons={diary:'📖',vitals:'📈',women:'🌷',meds:'💊',plans:'◷',quiz:'ABC',games:'♟',fortune:'☯',frame:'▣',phone:'☎',calendar:'▦',search:'⌕',trash:'♲',backup:'↗',settings:'⚙',night:'☾'};
function tile(k,sub=''){return `<button class="tile" data-action="nav:${k}" data-help="${k}"><span class="icon">${icons[k]||'✦'}</span><span><strong>${t(k)}</strong>${sub?`<small>${sub}</small>`:''}</span></button>`}
function nav(p){if(overlayCleanup){overlayCleanup();overlayCleanup=null}document.querySelectorAll('.overlay').forEach(e=>e.remove());page=p;render();window.scrollTo(0,0)}
function render(){document.querySelector('.site-notice').hidden=page!=='home';document.getElementById('creatorCredit').hidden=page!=='home';clearInterval(afterRender.clock);document.documentElement.lang=lang;document.body.classList.toggle('dark',!!S.settings.dark);document.body.classList.toggle('large',!!S.settings.large);$('lang').value=lang;document.querySelectorAll('[data-key]').forEach(e=>e.textContent=t(e.dataset.key));updateHelpButtons();$('helpBanner').hidden=!helpMode;$('helpBanner').textContent=L('説明モード：対象を３秒長押し／もう一度「?」で解除','Help mode: hold an item for 3 seconds. Tap ? to exit.','Mode aide : appui de 3 secondes. Touchez ? pour quitter.');const views={home:homeView,diary:diaryView,vitals:vitalsView,women:womenView,meds:medsView,plans:plansView,quiz:quizView,games:gamesView,fortune:fortuneView,frame:frameView,phone:phoneView,search:searchView,trash:trashView,backup:backupView,settings:settingsView,night:nightView};$('app').innerHTML=views[page]?views[page]():homeView();afterRender()}
function title(k){return `<h1 data-help="${k}">${t(k)}</h1>`}
function homeView(){const hidden=S.settings.hidden||[];return `<div class="brand" data-help="mirror" data-hold="mirror"><img src="logo.png" alt="ふわナース ふわナース" draggable="false"><small>${L('ロゴを１秒長押しで手鏡','Hold logo 1 second for mirror','Appuyez 1 seconde sur le logo : miroir')}</small></div><div class="row"><span class="chip">${new Date().toLocaleDateString({ja:'ja-JP',en:'en-GB',fr:'fr-FR'}[lang],{year:'numeric',month:'long',day:'numeric',weekday:'short'})}</span><small>${t('testing')}</small></div><h2>${L('今日も、自分のペースで。','Today, at your own pace.','Aujourd’hui, à votre rythme.')}</h2><button class="tile hero" data-action="nav:diary" data-help="diary"><span class="icon">📖</span><span><strong>${t('diary')}</strong><small>${L('写真も、ひとことも。','A photo, a few words.','Une photo, quelques mots.')}</small></span><span>›</span></button><h2>${L('からだと暮らし','Health & everyday life','Santé et quotidien')}</h2><div class="grid">${['vitals','women','meds','plans','calendar'].filter(k=>!hidden.includes(k)).map(k=>tile(k)).join('')}</div><h2>${L('ひと息の時間','A little break','Une petite pause')}</h2><div class="grid">${['quiz','games','fortune','frame','night'].filter(k=>!hidden.includes(k)).map(k=>tile(k)).join('')}</div><h2>${L('道具箱','Tools','Outils')}</h2><div class="grid">${['phone','search','backup','trash','settings'].map(k=>tile(k)).join('')}</div>${ownerView()}<footer>${L('個人の記録はこの端末に保存。こまめにバックアップを。','Personal records stay on this device. Back up regularly.','Données conservées sur cet appareil. Sauvegardez régulièrement.')}</footer>`}
function ownerView(){return `<section class="card" style="margin-top:24px" data-help="owner"><h2>${t('owner')}</h2><small>${L('各欄を２秒長押しで編集。編集ボタンでも開けます。','Hold a field for 2 seconds to edit, or use Edit.','Appui de 2 secondes pour modifier, ou bouton Modifier.')}</small><div class="checkrow" style="margin:12px 0"><input id="ownerVisible" type="checkbox" ${S.settings.ownerVisible?'checked':''}><label for="ownerVisible">${L('この情報を表示する','Show this information','Afficher ces informations')}</label></div>${S.settings.ownerVisible?`<div class="row"><div data-hold="owner" data-help="owner">${S.owner.photo?`<img class="avatar" src="${safeImage(S.owner.photo)}" alt="${t('photo')}">`:'◯ '+t('photo')}</div><div>${btn(t('edit'),'owner','','owner')}</div></div>${['name','address','tel','hospital','hospitalTel','doctor','emergency'].map(k=>`<div class="owner-field" data-hold="owner" data-help="owner"><strong>${t(k)}</strong>：${esc(S.owner[k]||t('unregistered'))}</div>`).join('')}`:btn(L('登録・編集','Register / edit','Saisir / modifier'),'owner','','owner')}<p class="muted" style="margin-top:12px">${L('登録・表示は任意です。ロック画面からは見られません。','Optional. Not accessible from the lock screen.','Facultatif. Non accessible depuis l’écran verrouillé.')}</p></section>`}
function safeImage(s){return /^data:image\/(jpeg|png|webp);base64,[A-Za-z0-9+/=]+$/.test(s||'')?s:''}
function entryCard(e){return `<article class="entry" data-help="${e.kind}"><div class="row"><strong>${esc(e.title||t(e.kind)||'')}</strong><small>${stamp(e.when)}</small></div>${e.body?`<p class="body">${esc(e.body)}</p>`:''}${e.values?`<p>${Object.entries(e.values).filter(([k,v])=>v!==''&&v!=null).map(([k,v])=>`${esc(labelFor(k))}：${esc(valueLabel(k,v))}`).join(' ／ ')}</p>`:''}${e.photos?.length?`<div class="photo-grid">${e.photos.map((p,i)=>`<img src="${safeImage(p.data)}" alt="${esc(p.caption||t('photo'))}" data-action="photo:${e.id}:${i}" data-help="photo">`).join('')}</div>`:''}<div class="row" style="margin-top:10px">${['diary','vitals','women'].includes(e.kind)?btn(t('edit'),'edit:'+e.id):''}${btn(t('del'),'trash:'+e.id,'danger')}</div></article>`}
function listEntries(arr){return arr.length?arr.slice(0,100).map(entryCard).join('')+(arr.length>100?`<p>${L('最新100件を表示。検索や期間指定で絞り込んでください。','Showing latest 100. Narrow the date range or search.','100 derniers éléments. Affinez la recherche.')}</p>`:''):`<p class="muted">${t('empty')}</p>`}
function diaryView(){return title('diary')+`<p>${L('診察の質問、配信のネタ、持ち物も自由に。','Questions, ideas, lists — anything you like.','Questions, idées, listes : écrivez librement.')}</p><div class="row">${btn(t('new'),'new:diary','primary')}${btn(t('search'),'nav:search')}</div><section class="card" style="margin-top:16px">${listEntries(active().filter(e=>e.kind==='diary'))}</section>`}
function active(){return S.entries.filter(e=>!e.deleted).sort((a,b)=>b.when.localeCompare(a.when))}
const valueOptions={mood:[['good','😊', 'Good','Bien'],['okay','😐','Okay','Moyen'],['low','😔','Low','Bas'],['tired','😴','Tired','Fatigué']],bowel:[['normal','普通','Normal','Normal'],['hard','硬い','Hard','Dur'],['loose','軟らかい','Loose','Mou'],['diarrhea','下痢','Diarrhoea','Diarrhée'],['none','なし','None','Aucun']],condition:[['waking','起床時','On waking','Au réveil'],['before','食前','Before meal','Avant repas'],['after','食後','After meal','Après repas'],['other','その他','Other','Autre']]};
function opts(k){return [['',L('未記入','Not recorded','Non renseigné')],...(valueOptions[k]||[]).map(v=>[v[0],L(v[1],v[2],v[3])])]}
function valueLabel(k,v){const a=(valueOptions[k]||W.find(w=>w[0]===k)?.[2]||[]).find(x=>x[0]===v);return a?L(a[1],a[2],a[3]):v}
function labelFor(k){return I[k]?t(k):(W.find(x=>x[0]===k)?.[1]?.[{ja:0,en:1,fr:2}[lang]]||k)}
function modal(html){const d=$('modal');d.innerHTML=`<div class="modal-tools">${btn('TOP','goTop')}${btn('?','toggleHelp','','help')}${btn(t('close'),'cancel')}</div><div id="modalHelpNotice"></div>`+html;d.showModal();updateHelpButtons();bindDials();}
function modalButtons(action='commit'){return `<div class="row">${btn(t('cancel'),'cancel')}${btn(t('save'),action,'primary')}</div>`}
let editId=null,editPhotos=[],editToken=0;
function dial(k,min,max,step,unit,value){return `<label class="checkrow"><input class="check" type="checkbox" id="on-${k}" ${value!=null?'checked':''}>${t(k)} (${unit})</label><div class="dial">${btn('−','step:'+k+':-1')}<input type="number" id="v-${k}" min="${min}" max="${max}" step="${step}" value="${value??min}">${btn('＋','step:'+k+':1')}</div>`}
function newEntry(kind,id){const session=++editToken;const e=id?S.entries.find(x=>x.id===id):null;editId=id||null;editPhotos=structuredClone(e?.photos||[]);const v=e?.values||{};let fields=field(t('date'),'entryWhen',e?.when||localDT(),'datetime-local','required')+field(t('title'),'entryTitle',e?.title||'');if(kind==='diary')fields+=select(t('category'),'entryCategory',[["",L('自由','Free','Libre')],['food',L('食事','Food','Repas')],['hospital',L('通院・入院','Hospital','Hôpital')],['ideas',L('配信・アイデア','Ideas','Idées')],['check',L('持ち物・チェック','Checklist','Liste')]],e?.category||'')+select(t('mood'),'mood',opts('mood'),v.mood||'')+select(t('bowel'),'bowel',opts('bowel'),v.bowel||'')+select(L('睡眠','Sleep','Sommeil'),'sleep',opts('sleep'),v.sleep||'')+select(L('だるさ・生活への影響','Fatigue / daily impact','Fatigue / retentissement'),'fatigue',opts('fatigue'),v.fatigue||'');if(kind==='vitals')fields+=dial('temp',30,45,.1,'℃',v.temp)+dial('sys',40,300,1,'mmHg',v.sys)+dial('dia',20,200,1,'mmHg',v.dia)+dial('glucose',10,700,1,'mg/dL',v.glucose)+select(t('condition'),'condition',opts('condition'),v.condition||'')+dial('pulse',20,250,1,L('回/分','bpm','bpm'),v.pulse)+`<small>${L('入力範囲外の測定値や「HI・LO」は、備考にそのまま残してください。','Values outside the dial range: write the exact reading in Notes.','Hors plage : notez la valeur exacte dans les notes.')}</small>`;if(kind==='women')fields+=womenFields(v);fields+=area(t('text'),'entryBody',e?.body||'')+`<label>${t('photo')} <input id="entryFiles" type="file" accept="image/*" multiple></label><small>${L('写真は長辺1600px以内に縮小して保存します。原本は別途保管してください。','Photos are resized to max 1600px. Keep originals separately.','Photos réduites à 1600 px maximum. Conservez les originaux.')}</small><div id="editPhotos" class="photo-grid"></div>`;modal(`<h1>${t(kind)}</h1><form id="entryForm" data-help="${kind}">${!id?`<p class="notice">${L('新規入力です。過去の記録を変更する場合は、一覧の「編集」を選んでください。','New entry. To change an existing record, select Edit in the list.','Nouvelle note. Pour modifier une note, utilisez Modifier dans la liste.')}</p>`:''}${fields}<div id="entryErr" role="alert"></div>${modalButtons('commit:'+kind)}</form>`);showEditPhotos();$('entryFiles').onchange=async ev=>{const input=ev.target;input.disabled=true;try{for(const f of input.files){const data=await imageData(f);if(session!==editToken||!$('modal').open)return;editPhotos.push({data,caption:f.name})}if($('editPhotos'))showEditPhotos()}catch(e){toast(e.message)}finally{input.disabled=false;input.value=''}}}
function showEditPhotos(){$('editPhotos').innerHTML=editPhotos.map((p,i)=>`<div><img src="${safeImage(p.data)}" alt="${t('photo')}">${btn('×','removePhoto:'+i)}</div>`).join('')}
async function imageData(file){if(file.size>30*1024*1024)throw Error(L('写真は１枚30MB以内にしてください','Use photos under 30MB','Photo : 30 Mo maximum'));return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onerror=()=>reject(Error('Read error'));reader.onload=()=>{const img=new Image();img.onerror=()=>reject(Error(L('この画像形式は読み込めません。JPEGなどでお試しください。','Cannot read this image. Try JPEG.','Image illisible. Essayez JPEG.')));img.onload=()=>{const factor=Math.min(1,1600/Math.max(img.width,img.height)),c=document.createElement('canvas');c.width=Math.round(img.width*factor);c.height=Math.round(img.height*factor);c.getContext('2d').drawImage(img,0,0,c.width,c.height);resolve(c.toDataURL('image/jpeg',.83))};img.src=reader.result};reader.readAsDataURL(file)})}
async function commitEntry(kind){if(!$('entryWhen').value){toast(L('日時を入力してください','Enter a date','Saisissez une date'));return}if($('entryFiles').disabled){toast(L('写真の処理中です','Processing photos','Traitement des photos'));return}const priorValues=S.entries.find(x=>x.id===editId)?.values||{};const values=['women','diary'].includes(kind)?structuredClone(priorValues):{};if(kind==='diary'){for(const k of ['mood','bowel','sleep','fatigue'])if($(k)&&!$(k).closest('[hidden]'))values[k]=$(k).value}if(kind==='vitals'){for(const k of ['temp','sys','dia','glucose','pulse'])if($('on-'+k).checked)values[k]=Number($('v-'+k).value);values.condition=$('condition').value}if(kind==='women')for(const w of W)if($('w-'+w[0]))values[w[0]]=$('w-'+w[0]).value;const old=S.entries.find(e=>e.id===editId);const e={...old,id:editId||uid(),kind,when:$('entryWhen').value,title:$('entryTitle').value,body:$('entryBody').value,category:$('entryCategory')?.value||'',values,photos:structuredClone(editPhotos),modified:Date.now()};if(!e.body.trim()&&!e.title.trim()&&!e.photos.length&&!Object.values(values).some(v=>v!=='')){toast(L('何か１つ記入してください','Add at least one item','Ajoutez au moins un élément'));return}if(await mutate(n=>{const i=n.entries.findIndex(x=>x.id===e.id);if(i>=0)n.entries[i]=e;else n.entries.push(e)})){closeModal();toast(t('saved'))}}
function closeModal(){editToken++;stopRecord();recordToken++;$('modal').close();setHelpMode(false)}
const W=[['bleed',['出血','Bleeding','Saignements'],[['none','なし','None','Aucun'],['spot','少量・点状','Spotting','Traces'],['light','少なめ','Light','Faible'],['moderate','中程度','Moderate','Modéré'],['heavy','多い','Heavy','Abondant']]],['discharge',['おりものの変化','Discharge changes','Pertes vaginales'],[['none','変化なし','Unchanged','Sans changement'],['amount','量の変化','Amount changed','Quantité modifiée'],['color','色の変化','Colour changed','Couleur modifiée'],['odor','においの変化','Odour changed','Odeur modifiée']]],['pain',['下腹部・骨盤の痛み','Pelvic / lower abdominal pain','Douleur pelvienne'],[['none','なし','None','Aucune'],['mild','軽い','Mild','Légère'],['medium','中程度','Moderate','Modérée'],['strong','強い','Severe','Forte']]],['urine',['排尿の変化','Urinary changes','Troubles urinaires'],[['none','なし','None','Aucun'],['difficult','出にくい','Difficulty','Difficulté'],['pain','痛い','Pain','Douleur'],['leak','尿漏れ','Leakage','Fuites']]],['swelling',['脚のむくみ','Leg swelling','Jambes gonflées'],[['none','なし','None','Aucune'],['left','左','Left','Gauche'],['right','右','Right','Droite'],['both','両方','Both','Deux côtés']]],['flush',['ほてり・寝汗','Hot flushes / night sweats','Bouffées de chaleur / sueurs'],[['none','なし','None','Aucune'],['mild','軽い','Mild','Légères'],['medium','中程度','Moderate','Modérées'],['strong','強い','Severe','Fortes']]],['menstruation',['月経','Menstruation','Règles'],[['start','開始','Started','Début'],['ongoing','継続中','Ongoing','En cours'],['end','終了','Ended','Fin'],['none','なし','None','Aucune']]]];
let range=30,metric='temp',glucoseFilter='';
function vitalsView(){return title('vitals')+btn(t('new'),'new:vitals','primary')+`<section class="card" style="margin-top:16px"><div class="tabs">${['temp','sys','glucose','pulse'].map(k=>btn(t(k==='sys'?'bp':k),`metric:${k}`,metric===k?'primary':'')).join('')}</div>${field(L('表示の終了日','Display end date','Date de fin'),'vitalEnd',vitalEnd,'date')}${select(t('period'),'range',[[7,L('１週間','1 week','1 semaine')],[30,L('１か月','1 month','1 mois')],[90,L('３か月','3 months','3 mois')],[365,L('１年','1 year','1 an')],[0,t('all')]].map(x=>[String(x[0]),x[1]]),String(range))}${metric==='glucose'?select(t('condition'),'glucoseFilter',[['',L('すべて','All','Tous')],...opts('condition').slice(1)],glucoseFilter):''}<div id="chart">${chartView()}</div></section><section class="card">${listEntries(vitalEntries())}</section>`}
function vitalEntries(){const anchor=new Date(vitalEnd+'T12:00:00'),cutoff=range?day(new Date(anchor.getTime()-(range-1)*86400000)):'';return active().filter(e=>e.kind==='vitals'&&e.when.slice(0,10)>=cutoff&&e.when.slice(0,10)<=vitalEnd&&(!glucoseFilter||metric!=='glucose'||e.values.condition===glucoseFilter))}
function chartView(){const entries=vitalEntries().slice().reverse(),keys=metric==='sys'?['sys','dia']:[metric],series=keys.map(k=>entries.filter(e=>Number.isFinite(e.values[k])).map(e=>({x:new Date(e.when).getTime(),y:e.values[k],when:e.when}))),points=series.flat();if(!points.length)return `<p>${t('empty')}</p>`;const minX=Math.min(...points.map(p=>p.x)),maxX=Math.max(...points.map(p=>p.x));let minY=Math.min(...points.map(p=>p.y)),maxY=Math.max(...points.map(p=>p.y));const pad=Math.max((maxY-minY)*.15,metric==='temp'?.2:5);minY-=pad;maxY+=pad;const X=x=>55+(x-minX)/(maxX-minX||1)*620,Y=y=>235-(y-minY)/(maxY-minY)*210;let svg=`<svg class="chart" viewBox="0 0 710 285" role="img" aria-label="${esc(t('vitals'))}">`;for(let i=0;i<5;i++){const val=minY+(maxY-minY)*i/4,y=Y(val);svg+=`<line x1="55" x2="680" y1="${y}" y2="${y}" stroke="var(--line)"/><text x="4" y="${y+4}" fill="var(--muted)" font-size="12">${val.toFixed(metric==='temp'?1:0)}</text>`}const colors=['#b84d66','#407da2'];series.forEach((p,i)=>{svg+=`<polyline fill="none" stroke="${colors[i]}" stroke-width="2" points="${p.map(a=>`${X(a.x)},${Y(a.y)}`).join(' ')}"/>`+p.map(a=>`<circle cx="${X(a.x)}" cy="${Y(a.y)}" r="4" fill="${colors[i]}"><title>${esc(stamp(a.when))} : ${a.y}</title></circle>`).join('')});svg+=`<text x="55" y="270" fill="var(--muted)" font-size="12">${day(new Date(minX))}</text><text x="675" y="270" text-anchor="end" fill="var(--muted)" font-size="12">${day(new Date(maxX))}</text></svg>`;return `<p>${metric==='temp'?'℃':metric==='glucose'?'mg/dL':metric==='pulse'?'bpm':'mmHg'}</p>`+svg+`<div class="legend">${keys.map((k,i)=>`<span style="color:${colors[i]}">● ${t(k)}</span>`).join('')}</div><small>${L('左右の点は測定日時順。点の間は未測定です。数値は下の記録で確認できます。','Points follow measurement times. Gaps do not imply measurements. Exact readings are listed below.','Points selon les dates de mesure. Valeurs exactes dans la liste ci-dessous.')}</small>`}
function womenView(){return womenMonthView()}
function womenSettings(){modal(`<h1>${t('women')}</h1>${W.map(w=>`<label class="checkrow" style="margin:14px 0"><input type="checkbox" id="show-${w[0]}" ${S.settings.hiddenWomen?.includes(w[0])?'':'checked'}>${L(...w[1])}</label>`).join('')}${modalButtons('saveWomenSettings')}`)}
function medsView(){return title('meds')+`<p class="notice">${L('通知の確認と服用記録は別です。飲んだか不明な場合、追加服用をアプリで判断しないでください。','Confirming an alert does not record a dose. If uncertain, do not use this app to decide on an extra dose.','Confirmer une alerte ne note pas une prise. En cas de doute, ne décidez pas d’une dose supplémentaire ici.')}</p>${btn(t('add'),'medEdit:new','primary')}<div style="margin-top:15px">${S.medications.filter(m=>!m.deleted).map(m=>`<section class="card"><h2>${esc(m.name)}</h2><p>${esc(m.dose)} · ${esc(m.times)}</p>${m.remaining!==''&&m.remaining!=null?`<p>${L('残数','Remaining','Restant')}：${esc(m.remaining)} ${stockUnit(m)}</p>`:''}<p>${esc(m.note)}</p>${medicineLinks(m)}<small>${L('直近の記録','Last record','Dernière note')}：${lastDose(m.id)}</small><div class="row" style="margin-top:12px">${btn(L('服用済み','Taken','Pris'),'dose:'+m.id+':taken','primary')}${btn(L('飲んだか不明','Unsure','Incertain'),'dose:'+m.id+':unsure')}</div><div class="row" style="margin-top:8px">${btn(t('edit'),'medEdit:'+m.id)}${btn(t('del'),'medTrash:'+m.id,'danger')}</div></section>`).join('')}</div><h2>${L('服用履歴','Dose history','Historique des prises')}</h2><section class="card">${listEntries(active().filter(e=>e.kind==='dose'))}</section>`}
function lastDose(id){const e=active().find(e=>e.medicationId===id);return e?esc(stamp(e.when)+' '+e.body):t('empty')}
function medEdit(id){const m=S.medications.find(x=>x.id===id)||{};modal(`<h1>${t('meds')}</h1>${field(L('薬名','Medication name','Nom du médicament'),'medName',m.name)}${field(L('製品の規格（例：１錠あたり5mg）','Product strength (e.g. 5 mg per tablet)','Dosage du produit (ex. 5 mg par comprimé)'),'medStrength',m.strength||'')}${field(L('１回の服用量：数字','Dose per administration: number','Quantité par prise : nombre'),'medDoseNumber',m.amount??'', 'number','min="0" step="any" inputmode="decimal"')}${select(L('服用量の単位','Dose unit','Unité de prise'),'medUnit',DOSE_UNITS,m.unit||'tablet')}${m.dose&&m.amount==null?`<p class="notice">${L('旧記録の量（数字欄へ自動変換しません）','Legacy dose (not auto-converted)','Ancienne dose (non convertie)')}：${esc(m.dose)}</p>`:''}${field(L('予定時刻・条件','Times / instructions','Horaires / consignes'),'medTimes',m.times)}${select(L('残数（任意・現物と照合）','Remaining (optional; check actual supply)','Restant (facultatif, vérifier le stock)'),'medRemaining',[['',L('管理しない','Not tracked','Non suivi')],...Array.from({length:1001},(_,i)=>[String(i),String(i)])],m.remaining==null?'':String(m.remaining))}${area(t('notes'),'medNote',m.note)}${field(L('確認済みの公式薬剤情報URL（任意）','Verified official medicine URL (optional)','URL officielle vérifiée (facultatif)'),'medInfoUrl',m.infoUrl||'','url')}<p>${L('薬効・副作用はPMDAの公式情報で確認します。薬名・規格を照合してください。','Check effects and side effects on PMDA; match the name and strength.','Vérifiez les effets avec PMDA et le nom/dosage exacts.')}</p>${modalButtons('medSave:'+id)}`)}
async function recordDose(id,status){const m=S.medications.find(x=>x.id===id);if(status==='taken'&&!confirm(L('服用済みとして記録しますか？','Record as taken?','Noter comme pris ?')))return;await mutate(n=>n.entries.push({id:uid(),kind:'dose',medicationId:id,when:localDT(),title:m.name,body:status==='taken'?L('服用済み','Taken','Pris'):L('飲んだか不明','Unsure','Incertain'),photos:[]}));toast(t('saved'))}
function plansView(){return title('plans')+`<p class="notice">${L('音声はこの画面を開いている間の補助機能です。ロック中・別アプリ使用中の通知はできません。重要な予定はiPhoneのアラームも併用してください。','Voice reminders work only while this page is active. No reliable alerts while locked or in another app. Use iPhone alarms for important reminders.','Rappels vocaux uniquement sur cette page active. Pas d’alerte fiable écran verrouillé. Utilisez aussi les alarmes iPhone.')}</p>${btn(t('add'),'planEdit:new','primary')} ${btn(L('音声を試す','Test voice','Tester la voix'),'voiceTest')}<div style="margin-top:16px">${S.plans.filter(p=>!p.deleted).sort((a,b)=>a.time.localeCompare(b.time)).map(p=>`<section class="card"><h2>${esc(p.time)}　${esc(p.title)}</h2><p>${esc(p.date)} · ${esc(repeatLabel(p.repeat))}</p><div class="row">${btn(p.enabled?L('有効','Enabled','Actif'):L('停止中','Paused','En pause'),'planToggle:'+p.id)}${btn(L('試し聞き','Listen','Écouter'),'planPlay:'+p.id)}${btn(t('edit'),'planEdit:'+p.id)}${btn(t('del'),'planTrash:'+p.id,'danger')}</div></section>`).join('')}</div>`}
const repeatLabel=r=>r==='daily'?L('毎日','Daily','Chaque jour'):r==='weekdays'?L('月〜金','Mon–Fri','Lun–ven'):L('指定日のみ','Once','Une fois');
function planEdit(id){const p=S.plans.find(x=>x.id===id)||{};pendingSound=p.sound||null;modal(`<h1>${t('plans')}</h1>${field(t('title'),'planTitle',p.title)}${field(L('日付','Date','Date'),'planDate',p.date||day(),'date')}${field(L('時刻','Time','Heure'),'planTime',p.time||localDT().slice(11,16),'time')}${select(L('繰り返し','Repeat','Répéter'),'planRepeat',[['once',L('指定日のみ','Once','Une fois')],['daily',L('毎日','Daily','Chaque jour')],['weekdays',L('月〜金','Mon–Fri','Lun–ven')]],p.repeat||'once')}<div class="row">${btn(L('録音開始','Record voice','Enregistrer la voix'),'recordStart')}${btn(L('録音停止','Stop recording','Arrêter'),'recordStop')}${btn(L('文字読み上げに戻す','Use text-to-speech','Lire le texte'),'recordClear')}</div><p id="recordStatus">${p.sound?L('録音あり','Voice recorded','Voix enregistrée'):L('文字を読み上げます','Text will be spoken','Le texte sera lu')}</p>${modalButtons('planSave:'+id)}`)}
let recordToken=0,recordProcessing=false;
async function startRecord(){const token=++recordToken;try{if(recording?.state==='recording')return;if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder)throw Error(L('この環境では録音できません。文字読み上げを使えます。','Recording unavailable. Use text-to-speech.','Enregistrement indisponible. Utilisez la synthèse vocale.'));const stream=await navigator.mediaDevices.getUserMedia({audio:true});audioChunks=[];recording=new MediaRecorder(stream);recording.ondataavailable=e=>{if(e.data.size)audioChunks.push(e.data)};recording.onstop=()=>{recordProcessing=true;const reader=new FileReader();reader.onload=()=>{recordProcessing=false;if(token!==recordToken||!$('modal').open)return;pendingSound=reader.result;if($('recordStatus'))$('recordStatus').textContent=L('録音を保存できます','Recording ready','Enregistrement prêt')};reader.readAsDataURL(new Blob(audioChunks,{type:recording.mimeType}));stream.getTracks().forEach(t=>t.stop());recording=null};recording.start();$('recordStatus').textContent=L('録音中（最長20秒）','Recording (max 20 seconds)','Enregistrement (20 s max)');clearTimeout(startRecord.limit);startRecord.limit=setTimeout(stopRecord,20000)}catch(e){toast(e.message)}}
function stopRecord(){clearTimeout(startRecord.limit);if(recording?.state==='recording')recording.stop()}
function speak(text){if(!window.speechSynthesis){toast(L('読み上げ非対応です','Speech unavailable','Synthèse vocale indisponible'));return}speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(text);u.lang={ja:'ja-JP',en:'en-US',fr:'fr-FR'}[lang];speechSynthesis.speak(u)}
function playPlan(p){if(p.sound){const a=new Audio(p.sound);a.play().catch(()=>toast(L('音声を再生できません。音量と設定を確認してください。','Audio blocked. Check volume and settings.','Audio bloqué. Vérifiez le volume.')))}else speak(p.title)}
let planShown=new Set();function tickPlans(){if(page!=='plans'||document.visibilityState!=='visible')return;const now=new Date(),date=day(now),time=localDT(now).slice(11,16);for(const p of S?.plans||[]){const key=p.id+date;if(p.voiceOnly||['done','cancelled'].includes(p.progress?.[date])||!p.enabled||p.deleted||p.time!==time||planShown.has(key)||p.lastAlert===date)continue;const match=p.repeat==='daily'||p.repeat==='weekdays'&&now.getDay()>0&&now.getDay()<6||p.repeat==='once'&&p.date===date;if(match){planShown.add(key);mutate(n=>{n.plans.find(x=>x.id===p.id).lastAlert=date},{undo:false,refresh:false});if(S.settings.quietMode===false)playPlan(p);toast(p.title)}}}
function phoneView(){return title('phone')+`<p>${L('横スライドで発信確認。名前部分を２秒長押しで編集。','Slide to confirm a call. Hold the name 2 seconds to edit.','Glissez pour appeler. Appui de 2 secondes pour modifier.')}</p><p class="muted">${L('iPhone側の確認後に発信します。','iPhone asks for confirmation before calling.','L’iPhone demande confirmation avant l’appel.')}</p>${S.contacts.map((c,i)=>`<div class="slider" data-contact="${i}" data-help="phone"><div class="track"></div><div class="handle" data-hold="contact:${i}" data-help="phone"><strong>${String(i+1).padStart(2,'0')}　${esc(c.name||t('unregistered'))}</strong><small>${esc(c.number||'→')}</small></div><span class="end">☎</span></div>`).join('')}`}
function contactEdit(i){const c=S.contacts[i];modal(`<h1>${t('phone')} ${i+1}</h1>${field(t('name'),'contactName',c.name)}${field(t('tel'),'contactNumber',c.number,'tel','inputmode="tel"')}${modalButtons('contactSave:'+i)}`)}
function ownerEdit(){modal(`<h1>${t('owner')}</h1><label>${t('photo')}<input id="ownerPhoto" type="file" accept="image/*"></label>${['name','address','tel','hospital','hospitalTel','doctor','emergency'].map(k=>field(t(k),'o-'+k,S.owner[k]||'',k==='tel'||k==='hospitalTel'?'tel':'text')).join('')}${modalButtons('ownerSave')}`)}
let calendarMonth=day().slice(0,7),searchText='',searchFrom='',searchTo='';
function calendarView(){return diaryView()}
function searchView(){return title('search')+`<section class="card">${field(L('本文・見出し・備考を部分一致検索','Search titles, text and notes','Rechercher dans les titres et notes'),'searchText',searchText,'search')}<div class="row">${field(L('開始日','From','Du'),'searchFrom',searchFrom,'date')}${field(L('終了日','To','Au'),'searchTo',searchTo,'date')}</div>${btn(t('search'),'doSearch','primary')} ${btn(L('条件をクリア','Clear filters','Effacer les filtres'),'clearSearch')}</section><section class="card" id="searchResults">${searchResults()}</section>`}
function searchResults(){const q=searchText.normalize('NFKC').toLocaleLowerCase();const arr=active().filter(e=>(!searchFrom||e.when.slice(0,10)>=searchFrom)&&(!searchTo||e.when.slice(0,10)<=searchTo)&&JSON.stringify([e.title,e.body,e.category,...(e.photos||[]).map(p=>p.caption),e.values]).normalize('NFKC').toLocaleLowerCase().includes(q));return `<p>${arr.length} ${L('件','records','éléments')}</p>`+listEntries(arr)}
function trashView(){const entries=S.entries.filter(e=>e.deleted).sort((a,b)=>b.deleted-a.deleted),meds=S.medications.filter(m=>m.deleted),plans=S.plans.filter(p=>p.deleted);return title('trash')+`<p>${L('完全削除するまで残ります。ごみ箱も保存容量を使います。','Items remain until permanently deleted and use storage space.','Les éléments restent et occupent de l’espace jusqu’à suppression définitive.')}</p><section class="card">${[...entries.map(e=>({type:'entry',id:e.id,label:(e.title||t(e.kind))+' · '+stamp(e.when)})),...meds.map(e=>({type:'med',id:e.id,label:e.name})),...plans.map(e=>({type:'plan',id:e.id,label:e.title}))].map(e=>`<div class="entry"><p>${esc(e.label)}</p><div class="row">${btn(t('restore'),`restore:${e.type}:${e.id}`)}${btn(L('完全削除','Delete permanently','Supprimer définitivement'),`purge:${e.type}:${e.id}`,'danger')}</div></div>`).join('')||t('empty')}</section>`}
function backupView(){return title('backup')+`<section class="card"><h2>${L('写真・記録・設定を一式保存','Save photos, records and settings','Sauvegarder photos, données et réglages')}</h2><p>${L('書き出したファイルを、別の端末や自分のクラウドにも保管してください。住所・病歴などが含まれるため、他人には渡さないでください。','Keep the exported file on another device or your own cloud. It contains private health/contact data; do not share it.','Conservez le fichier sur un autre appareil ou votre cloud. Il contient des données privées : ne le partagez pas.')}</p>${btn(L('バックアップを書き出す','Export backup','Exporter la sauvegarde'),'export','primary')}<p style="margin-top:12px">${L('最終書き出し','Last export','Dernier export')}：${S.lastBackup?stamp(S.lastBackup):t('unregistered')}</p><h2>${L('新しいスマホで読み込む','Import on a new phone','Importer sur un nouveau téléphone')}</h2><p>${L('読み込みは現在の記録を置き換えます。先に現在のバックアップを書き出してください。','Import replaces current records. Export the current backup first.','L’import remplace les données actuelles. Exportez-les d’abord.')}</p><input id="importFile" type="file" accept=".json,application/json"><div id="importInfo"></div><p class="notice">${L('ファイルは暗号化されていません。ブラウザーのデータ削除・端末故障では端末内記録も失われます。ごみ箱もバックアップに含みます。','Backup files are not encrypted. Browser data clearing or device loss can erase local records. Trash is included.','Les fichiers ne sont pas chiffrés. Effacer les données du navigateur peut supprimer les notes. La corbeille est incluse.')}</p></section><section class="card"><h2>${L('保存領域','Storage','Stockage')}</h2><p id="storageInfo">…</p></section>`}
function validBackup(v){if(!v||!['watashiplus-backup','koropitaru-backup'].includes(v.format)||v.version!==1||!v.state||v.state.schema!==1)throw Error(L('ふわナースの対応バックアップではありません','Unsupported backup format','Format de sauvegarde non pris en charge'));const s=v.state;for(const key of ['entries','medications','plans','contacts','frames'])if(!Array.isArray(s[key]))throw Error('Invalid '+key);if(s.contacts.length!==30||s.frames.length>3||!s.settings||!s.owner||!s.fortune)throw Error('Invalid state');const ids=new Set();for(const e of s.entries){if(typeof e.id!=='string'||ids.has(e.id)||typeof e.kind!=='string'||typeof e.when!=='string'||!Number.isFinite(new Date(e.when).getTime())||!Array.isArray(e.photos))throw Error('Invalid record');ids.add(e.id);if(e.photos.some(p=>!safeImage(p.data)))throw Error('Invalid photo')}for(const m of s.medications)if(!m||typeof m.id!=='string'||typeof m.name!=='string'||typeof m.dose!=='string'||typeof m.times!=='string'||typeof m.note!=='string')throw Error('Invalid medication');for(const f of Object.values(s.fortune))if(!f||!Array.isArray(f.lines)||f.lines.length!==6||f.lines.some(n=>![6,7,8,9].includes(n)))throw Error('Invalid fortune');for(const p of s.frames)if(p!==null&&!safeImage(p))throw Error('Invalid frame');if(s.owner.photo&&!safeImage(s.owner.photo))throw Error('Invalid owner photo');if(s.contacts.some(c=>typeof c.name!=='string'||typeof c.number!=='string'))throw Error('Invalid contacts');if(!['ja','en','fr'].includes(s.settings.lang)||!Array.isArray(s.settings.hidden))throw Error('Invalid settings');for(const p of s.plans)if(typeof p.title!=='string'||typeof p.time!=='string'||!/^\d\d:\d\d$/.test(p.time)||p.sound&&!/^data:audio\/[a-zA-Z0-9.;=+\/-]+;base64,[A-Za-z0-9+/=]+$/.test(p.sound))throw Error('Invalid plan');return normaliseState(s)}
async function exportBackup(){const now=new Date().toISOString();const state=structuredClone(S);state.lastBackup=now;const blob=new Blob([JSON.stringify({format:'watashiplus-backup',version:1,exportedAt:now,state})],{type:'application/json'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='watashiplus-backup-'+day()+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),60000);await mutate(n=>n.lastBackup=now,{undo:false});toast(L('書き出しを開始しました。ファイルが保存されたか確認してください。','Export started. Check that the file was saved.','Export lancé. Vérifiez que le fichier a bien été enregistré.'))}
async function importBackup(file){try{if(file.size>350*1024*1024)throw Error(L('350MBを超えるファイルはこの試用版では読み込めません','Trial import limit: 350MB','Limite d’importation : 350 Mo'));const parsed=JSON.parse(await file.text()),s=validBackup(parsed);$('importInfo').innerHTML=`<p>${s.entries.length} ${L('件の記録','records','notes')} / ${s.frames.length} ${t('photo')}</p>${btn(L('確認して置き換える','Confirm replacement','Confirmer le remplacement'),'importConfirm','danger')}`;window.pendingImport=s}catch(e){toast(L('読み込めませんでした：','Import failed: ','Échec de l’import : ')+e.message)}}
function settingsView(){return title('settings')+`<section class="card"><label class="checkrow"><input id="darkSetting" type="checkbox" ${S.settings.dark?'checked':''}>${L('暗い画面','Dark theme','Thème sombre')}</label><br><label class="checkrow"><input id="largeSetting" type="checkbox" ${S.settings.large?'checked':''}>${L('文字を大きく','Larger text','Texte agrandi')}</label><h2>${L('表紙に表示する項目','Visible home sections','Rubriques visibles')}</h2><p>${t('settingsNote')}</p>${['diary','vitals','women','meds','plans','quiz','games','fortune','frame','night'].map(k=>`<label class="checkrow" style="margin:10px 0"><input id="visible-${k}" type="checkbox" ${S.settings.hidden.includes(k)?'':'checked'}>${t(k)}</label>`).join('')}${btn(t('save'),'saveSettings','primary')}</section><section class="card"><h2>${t('readme')}</h2><p>${L('操作説明：? を押して説明モードをオンにし、対象を３秒長押し。通常時はロゴ１秒で鏡、電話帳・持主情報は２秒で編集できます。','Help: tap ? and hold an item for 3 seconds. Normally, hold the logo 1 second for mirror; contacts and owner fields 2 seconds to edit.','Aide : touchez ?, puis appuyez 3 secondes sur un élément. Logo : 1 s pour le miroir. Contacts et identité : 2 s pour modifier.')}</p><p>${L('画像・音声は外部送信しません。端末の消音、音量、ブラウザー設定によって音声が鳴らない場合があります。','Images and audio are not uploaded. Mute, volume and browser settings may block sound.','Images et sons ne sont pas envoyés. Le mode silencieux et les réglages peuvent bloquer le son.')}</p></section>`}
function frameView(){return title('frame')+`<section class="card"><p>${L('大切な写真を３枚まで。ここで選んだ写真はバックアップにも含まれます。','Up to three favourite photos, included in backups.','Jusqu’à trois photos, incluses dans les sauvegardes.')}</p><div class="photo-grid">${[0,1,2].map(i=>`<div>${S.frames[i]?`<img src="${safeImage(S.frames[i])}" alt="${i+1}" data-action="showFrame:${i}">`:`<div style="height:120px;text-align:center;padding:30px">${i+1} ▣</div>`}<label>${L('写真を選ぶ','Choose photo','Choisir une photo')}<input type="file" accept="image/*" data-frame="${i}"></label></div>`).join('')}</div>${S.frames.length?btn(L('写真立てを開く','Open photo frame','Ouvrir le cadre'),'showFrame:0','primary'):''}<p class="muted">${L('最初の３枚は未提供です。今はご自身の写真で試せます。','The three gift photos are not supplied yet. You can try your own.','Les trois photos du cadeau restent à fournir. Essayez les vôtres.')}</p></section>`}
function showPhotos(photos,index=0,mirror=false){if(!photos.length)return;let i=index,controls=true,startX=0;const el=document.createElement('div');el.className='overlay frame';el.innerHTML=`<div class="controls">${btn(t('back'),'overlayClose')}<span id="frameCount"></span>${btn('‹','framePrev')}${btn('›','frameNext')}</div><img id="bigPhoto" alt="${t('photo')}">`;document.body.append(el);function paint(){$('bigPhoto').src=photos[i];$('frameCount').textContent=`${i+1} / ${photos.length}`}paint();el.addEventListener('click',ev=>{const a=ev.target.closest('[data-action]')?.dataset.action;if(a==='framePrev')i=(i+photos.length-1)%photos.length;else if(a==='frameNext')i=(i+1)%photos.length;else if(!a){controls=!controls;el.querySelector('.controls').style.opacity=controls?'1':'0';return}paint()});el.onpointerdown=e=>startX=e.clientX;el.onpointerup=e=>{if(Math.abs(e.clientX-startX)>45){i=(i+(e.clientX<startX?1:photos.length-1))%photos.length;paint()}}}
async function mirror(){try{if(!navigator.mediaDevices?.getUserMedia)throw Error('Camera unavailable');const stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:'user'},audio:false});const el=document.createElement('div');el.className='overlay';el.dataset.hold='mirrorClose';el.dataset.help='mirror';el.innerHTML=`<video autoplay muted playsinline></video><div style="position:absolute;top:15px;right:15px;z-index:2">${btn(t('close'),'overlayClose')}</div><p class="mirror-note">${L('２秒長押しで戻る','Hold 2 seconds to return','Appui de 2 secondes pour revenir')}</p>`;document.body.append(el);el.querySelector('video').srcObject=stream;overlayCleanup=()=>stream.getTracks().forEach(t=>t.stop())}catch(e){toast(L('カメラを開けません。Safariのカメラ許可を確認してください。','Cannot open camera. Check Safari camera permission.','Caméra inaccessible. Vérifiez l’autorisation Safari.'))}}
let audioCtx,noiseNode;function stopNoise(){if(noiseNode){noiseNode.stop();noiseNode=null}if(audioCtx){audioCtx.close();audioCtx=null}}
function nightView(){return title('night')+`<section class="card" style="text-align:center"><div id="clock" style="font-size:3.2em;font-variant-numeric:tabular-nums">${new Date().toLocaleTimeString()}</div><p>${L('音はイヤホンで。周囲への配慮を。','Use headphones and respect others.','Utilisez des écouteurs, respectez les autres.')}</p><div class="row">${btn(L('静かな雨音','Soft rain','Pluie douce'),'noise')}${btn(L('停止','Stop','Arrêter'),'noiseStop')}</div><p>${L('雨音は端末内で合成します。','Rain is synthesized on device.','Pluie synthétisée sur l’appareil.')}</p></section>`}
function playNoise(){stopNoise();try{audioCtx=new(window.AudioContext||window.webkitAudioContext)();const b=audioCtx.createBuffer(1,audioCtx.sampleRate*3,audioCtx.sampleRate),d=b.getChannelData(0);let prev=0;for(let i=0;i<d.length;i++){prev=(prev+.04*(Math.random()*2-1))/1.05;d[i]=prev*3.5}noiseNode=audioCtx.createBufferSource();noiseNode.buffer=b;noiseNode.loop=true;const gain=audioCtx.createGain();gain.gain.value=.15;noiseNode.connect(gain).connect(audioCtx.destination);noiseNode.start()}catch(e){toast(e.message)}}
const EN_BANK=[];
