function unitLabel(unit){const map={tablet:['錠','tablet(s)','comprimé(s)'],packet:['包','packet(s)','sachet(s)'],capsule:['カプセル','capsule(s)','gélule(s)'],drop:['滴','drop(s)','goutte(s)'],puff:['吸入','puff(s)','bouffée(s)'],other:['その他','other','autre']};return map[unit]?L(...map[unit]):unit}
function normaliseState(s){return s}
function womenFields(v){return `<p class="notice">${L('すべて任意です。回数・尿量は１日の累計。尿量は医療者の指示がある場合だけ記入してください。','All optional. Counts and volume are daily totals. Record volume only if instructed.','Tout est facultatif. Nombres et volume : totaux du jour. Volume uniquement sur consigne.')}</p>`+W.filter(w=>!S.settings.hiddenWomen?.includes(w[0])).map(w=>{const num=W_NUMBERS[w[0]];let options=w[2];if(num)options=Array.from({length:num.max/num.step+1},(_,i)=>[String(i*num.step),String(i*num.step)]);return select(L(...w[1]),'w-'+w[0],[['',L('未記入','Not recorded','Non renseigné')],...options.map(v=>[v[0],num?v[1]:L(...v.slice(1))])],v[w[0]]??'')}).join('')}
const oldValueLabel=valueLabel;valueLabel=function(k,v){return W_NUMBERS[k]?String(v):oldValueLabel(k,v)};
let vitalEnd=day(),womenMonth=day().slice(0,7),monthFit=false;
function monthRows(){return [...W,['sleep',I.sleep,valueOptions.sleep],['fatigue',I.fatigue,valueOptions.fatigue]]}
function relevantWomen(date){return active().filter(e=>e.when.slice(0,10)===date&&['women','diary'].includes(e.kind)).sort((a,b)=>a.when.localeCompare(b.when)||(a.modified||0)-(b.modified||0))}
function summaryCell(key,date){const entries=relevantWomen(date),values=entries.map(e=>e.values?.[key]).filter(v=>v!==''&&v!=null);if(!values.length)return {symbol:'',detail:L('未記録','Not recorded','Non renseigné'),grade:'blank'};
 if(W_NUMBERS[key]){const value=values[values.length-1];return {symbol:String(value),detail:L('最新の１日累計','Latest daily total','Dernier total du jour')+': '+value,grade:'numeric'}}
 const auxiliary={bleedColor:{red:['赤','R','R'],pink:['桃','P','Rse'],brown:['褐','Br','Br']},swelling:{none:['○','○','○'],left:['△左','△L','△G'],right:['△右','△R','△D'],both:['△両','△B','△2']},painSite:{abdomen:['腹','Ab','Ab'],pelvis:['骨','Pe','Ba'],back:['腰','Bk','Do'],other:['他','Et','Au']},painDuration:{brief:['短','Br','Br'],intermittent:['断','Int','Int'],continuous:['続','Con','Con']},swellingSite:{ankle:['足','An','Ch'],calf:['脛','Ca','Mo'],thigh:['腿','Th','Cu'],groin:['付','Gr','Ai'],multiple:['複','Mul','Mul']},menstruation:{none:['○','○','○'],start:['△始','△S','△D'],ongoing:['△中','△O','△C'],end:['□終','□E','□F']}};
 if(auxiliary[key]){const v=values[values.length-1];return{symbol:L(...(auxiliary[key][v]||[String(v)])),detail:valueLabel(key,v),grade:'aux'}}
 const rank=v=>({none:0,normal:0,good:0,okay:0,spot:1,light:1,mild:1,medium:2,moderate:2,strong:3,heavy:3,reduced:1,absent:2,present:1,amount:1,color:1,odor:1,difficult:1,pain:1,leak:1}[v]??1);
 const v=values.reduce((a,b)=>rank(b)>=rank(a)?b:a),r=rank(v);return {symbol:r===0?'○':r===1?'△':'□',detail:[...new Set(values.map(v=>valueLabel(key,v)))].join(' / '),grade:r===0?'good':r===1?'mild':'strong'};
}
function womenMonthView(){const [year,month]=womenMonth.split('-').map(Number),n=new Date(year,month,0).getDate(),rows=monthRows().filter(w=>!S.settings.hiddenWomen?.includes(w[0]));return title('women')+`<p>${L('縦に項目、横に日付。マスを押して、その日の記録・変更へ。','Rows are items, columns are dates. Tap a cell to view or edit a day.','Lignes : rubriques, colonnes : jours. Touchez une case pour consulter ou modifier.')}</p><section class="card"><div class="row">${btn('‹','womenPrev')}${field(L('表示月','Month','Mois'),'womenMonth',womenMonth,'month')}${btn('›','womenNext')}</div><div class="row">${btn(t('new'),'new:women','primary')}${btn(L('項目を選ぶ','Choose fields','Choisir les champs'),'womenSettings')}${btn(monthFit?L('拡大して横移動','Enlarge & scroll','Agrandir et défiler'):L('全月を見渡す','Fit full month','Voir tout le mois'),'monthFit')}</div><p class="legend"><span>○ ${L('なし・いつもどおり','None / usual','Aucun / habituel')}</span><span>△ ${L('軽い・変化あり','Mild / change','Léger / changement')}</span><span>□ ${L('中程度以上','Moderate or more','Modéré ou plus')}</span></p><small>${L('空欄＝未記録。記号は医学的な判定ではありません。同日の程度は最も強い状態、回数・尿量は最新の累計、部位・月経は最新の状態です。詳しくはマスを押してください。','Blank = not recorded. Symbols are not medical judgments. Daily severity uses the highest reported level; totals, locations and periods use the latest value. Tap for details.','Vide = non renseigné. Symboles sans jugement médical. Intensité maximale du jour ; totaux et catégories : dernière valeur. Touchez pour les détails.')}</small><div class="month-scroll ${monthFit?'fit-month':''}" style="--days:${n}"><table class="month-table"><thead><tr><th>${L('項目','Item','Rubrique')}</th>${Array.from({length:n},(_,i)=>`<th>${i+1}</th>`).join('')}</tr></thead><tbody>${rows.map(w=>`<tr><th>${esc(L(...w[1]))}</th>${Array.from({length:n},(_,i)=>{const date=womenMonth+'-'+String(i+1).padStart(2,'0'),cell=summaryCell(w[0],date);return `<td class="${cell.grade}"><button data-action="womenDay:${date}:${w[0]}" data-help="women" title="${esc(date+' '+L(...w[1])+' '+cell.detail)}" aria-label="${esc(date+' '+L(...w[1])+' '+cell.detail)}">${esc(cell.symbol)||'&nbsp;'}</button></td>`}).join('')}</tr>`).join('')}</tbody></table></div><p class="muted">${L('「赤・桃・褐」は色、「左・右・両」は左右、「始・中・終」は月経の開始・継続・終了。数値欄は記録した数です。睡眠・だるさは日記帳で入力します。','Auxiliary letters indicate colour, side, location and period stage. Numeric fields show recorded counts. Sleep and fatigue are entered in the journal.','Les lettres indiquent couleur, côté, lieu et stade des règles. Les nombres sont ceux saisis. Sommeil et fatigue se notent dans le journal.')}</p></section>`}
function openWomenDay(date,key){const arr=relevantWomen(date);modal(`<h1>${esc(date)}</h1><h2>${esc(labelFor(key))}</h2><p>${esc(summaryCell(key,date).detail)}</p><div class="row">${btn(L('この日に記録を追加','Add record for this day','Ajouter une note ce jour'),'womenAdd:'+date+':'+key,'primary')}${btn(t('close'),'cancel')}</div>${arr.length?listEntries(arr):`<p>${t('empty')}</p>`}`)}
function shiftMonth(d){const [y,m]=womenMonth.split('-').map(Number),date=new Date(y,m-1+d,1);womenMonth=day(date).slice(0,7);render()}
function syncDial(id){const s=$(id),o=document.querySelector(`[data-dial="${id}"]`);if(!s||!o)return;o.textContent=s.value;o.setAttribute('aria-valuenow',s.value);o.setAttribute('aria-valuemin',s.options[0].value);o.setAttribute('aria-valuemax',s.options[s.options.length-1].value)}
function moveDial(id,delta){const s=$(id);if(!s)return;const i=Math.max(0,Math.min(s.options.length-1,s.selectedIndex+delta));s.selectedIndex=i;const check=$('on-'+id.slice(2));if(check)check.checked=true;syncDial(id)}

function bindDials(){document.querySelectorAll('[data-dial]').forEach(el=>{el.onwheel=e=>{if(helpMode)return;e.preventDefault();if(e.deltaY)moveDial(el.dataset.dial,e.deltaY<0?1:-1)};el.onkeydown=e=>{if(helpMode)return;if(['ArrowUp','ArrowDown'].includes(e.key)){e.preventDefault();moveDial(el.dataset.dial,e.key==='ArrowUp'?1:-1)}};let y=null;el.onpointerdown=e=>{if(helpMode)return;e.preventDefault();e.stopPropagation();y=e.clientY;el.setPointerCapture(e.pointerId)};el.onpointermove=e=>{if(y==null||helpMode)return;const steps=Math.trunc((y-e.clientY)/16);if(steps){moveDial(el.dataset.dial,steps);y-=steps*16}};el.onpointerup=el.onpointercancel=()=>y=null})}
function updateHelpButtons(){const label=helpMode?L('? 説明ON','? Help ON','? Aide ON'):L('? 説明OFF','? Help OFF','? Aide OFF');document.querySelectorAll('#helpBtn,[data-action="toggleHelp"]').forEach(b=>{b.textContent=label;b.classList.toggle('help-on',helpMode);b.setAttribute('aria-pressed',String(helpMode))});const notice=$('modalHelpNotice');if(notice)notice.innerHTML=helpMode?`<p class="notice">${L('説明モード：対象を３秒長押し。? で解除。閉じる・キャンセル・TOPはいつでも使えます。','Help mode: hold an item 3 seconds. Tap ? to exit. Close, Cancel and TOP always work.','Mode aide : appui de 3 s. ? pour quitter. Fermer, Annuler et TOP restent utilisables.')}</p>`:''}
function setHelpMode(value){helpMode=value;updateHelpButtons();$('helpBanner').hidden=!helpMode;$('helpBanner').textContent=L('説明モード：対象を３秒長押し／?で解除','Help: hold an item 3 seconds / ? to exit','Aide : appui de 3 s / ? pour quitter')}
function goTop(){if($('modal').open)closeModal();setHelpMode(false);stopNoise();nav('home')}
