const oldMedEdit=medEdit;medEdit=function(id){oldMedEdit(id);$('modal').dataset.medId=id;const labels={tablet:['錠','tablet(s)','comprimé(s)'],packet:['包','packet(s)','sachet(s)'],capsule:['カプセル','capsule(s)','gélule(s)'],drop:['滴','drop(s)','goutte(s)'],puff:['吸入','puff(s)','bouffée(s)'],other:['その他（備考へ）','Other (notes)','Autre (notes)']};[...$('medUnit').options].forEach(o=>{if(labels[o.value])o.textContent=L(...labels[o.value])})};
function drugInfo(id){const m=S.medications.find(m=>m.id===id);modal(`<h1>${L('薬効・副作用の確認','Medicine information','Informations du médicament')}</h1><h2>${esc(m.name)}</h2><p>${L('製品規格','Product strength','Dosage du produit')}：${esc(m.strength||t('unregistered'))}</p><p class="notice">${L('同名・規格違いを避けるため、公式サイトで正式名・規格を照合します。自動で薬効を推測しません。すべての薬に患者向けガイドがあるわけではありません。','Match the exact product name and strength on the official site. No automatically inferred effects. Not all products have patient guides.','Vérifiez nom et dosage exacts sur le site officiel. Aucun effet déduit automatiquement. Certains produits n’ont pas de guide patient.')}</p>${btn(L('薬名をコピー','Copy medicine name','Copier le nom'),'copyDrug:'+id)}<p style="margin-top:14px"><a class="official-link" href="https://www.pmda.go.jp/okusuri_search/" target="_blank" rel="noopener noreferrer">${L('PMDAおくすりサーチを開く','Open PMDA medicine search','Ouvrir la recherche PMDA')} ↗</a></p>${m.infoUrl&&officialMedicineUrl(m.infoUrl)?`<p><a class="official-link" href="${esc(m.infoUrl)}" target="_blank" rel="noopener noreferrer">${L('登録した公式薬剤情報を開く','Open saved official information','Ouvrir la fiche officielle enregistrée')} ↗</a></p>`:''}<small>${L('公式情報を検索・閲覧する通信量はふわナースの計測に含まれません。','Traffic on the external information site is not included in this app’s estimate.','Le trafic du site externe n’est pas inclus dans l’estimation.')}</small><div style="margin-top:15px">${btn(t('close'),'cancel')}</div>`)}
