function showSummary105(){const from=$('summaryFrom105').value,to=$('summaryTo105').value;if(!from||!to||from>to){toast('期間を確認してください');return}const arr=active().filter(e=>e.when.slice(0,10)>=from&&e.when.slice(0,10)<=to),parts=[];for(const e of arr){let content='';if(e.kind==='vitals'&&$('summary-vitals105').checked||e.kind==='women'&&$('summary-women105').checked)content=Object.entries(e.values||{}).filter(([,v])=>v!==''&&v!=null).map(([k,v])=>esc(labelFor(k))+'：'+esc(valueLabel(k,v))).join(' ／ ');if(isHealth107(e)&&$('summary-quick105').checked)content=(e.category==='healthquick'?esc(e.body||''):'')+' '+Object.entries(e.values||{}).map(([k,v])=>esc(k)+'：'+esc(v)).join(' ／ ');if(e.category==='question'&&!e.done&&$('summary-questions105').checked)content=esc(e.title)+' '+esc(e.body||'');if(content)parts.push(`<article class="entry"><strong>${esc(stamp(e.when))}</strong><p class="body">${content}</p></article>`)}$('summaryResult105').innerHTML='<h2>診察用まとめ</h2>'+ (parts.join('')||'<p>選んだ期間の記録はありません。</p>')}
