function coverHome105(){if(page==='home'&&!$('modal').open&&!document.querySelector('.overlay,.help-page'))return;stopRepeat();stopSeason();stopNoise();stopRecord();if(window.speechSynthesis)speechSynthesis.cancel();if(overlayCleanup)closeOverlay();document.querySelectorAll('.overlay,.help-page').forEach(el=>el.remove());const d=$('modal');if(d.open){conceal105={nodes:[...d.childNodes],seed:modalSeed,changed:modalChanged,editId,photos:structuredClone(editPhotos),sound:pendingSound};d.close();d.replaceChildren()}setHelpMode(false);nav('home');}
function shakeSample105(e){if(!S?.settings.shakeHome||document.hidden)return;const a=e.accelerationIncludingGravity;if(!a||![a.x,a.y,a.z].every(Number.isFinite))return;const now=Date.now(),v=[a.x,a.y,a.z];if(lastMotion105&&now-shakeCooldown105>1500){const delta=Math.hypot(...v.map((x,i)=>x-lastMotion105[i]));if(delta>23&&(!shakeHits105.length||now-shakeHits105.at(-1)>100)){shakeHits105.push(now);shakeHits105=shakeHits105.filter(t=>now-t<800);if(shakeHits105.length>=2){shakeCooldown105=now;shakeHits105=[];coverHome105()}}}lastMotion105=v}
function listenShake105(){if(shakeListening)return;window.addEventListener('devicemotion',shakeSample105);shakeListening=true}
async function setShake105(){if(S.settings.shakeHome){await mutate(n=>n.settings.shakeHome=false);window.removeEventListener('devicemotion',shakeSample105);shakeListening=false;return}if(!window.isSecureContext||!('DeviceMotionEvent'in window)){toast('この環境では振って戻る機能を使えません。「表紙へ」ボタンをご利用ください。');return}try{if(typeof DeviceMotionEvent.requestPermission==='function'&&await DeviceMotionEvent.requestPermission()!=='granted'){toast('動きの利用が許可されませんでした');return}if(await mutate(n=>n.settings.shakeHome=true))listenShake105();toast('有効にしました。端末を持ったまま軽く２回振ってお試しください。')}catch{toast('動きを利用できません。「表紙へ」ボタンをご利用ください。')}}
