document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b)return;const [a,id,arg]=b.dataset.action.split(':');if(!['open105','sym105','quickSave105','checkAdd105','summaryShow105','simpleSave105','order105','shake105','resume105','planStatus105','planChange105','quiet105','checkTrash105'].includes(a))return;e.preventDefault();e.stopImmediatePropagation();if(helpMode)return;try{if(a==='open105'){if(id==='quick')quick105();if(id==='questions')checklist105('question');if(id==='requests')checklist105('request');if(id==='summary')summary105()}if(a==='sym105'){const on=b.getAttribute('aria-pressed')==='true';b.setAttribute('aria-pressed',String(!on));b.classList.toggle('selected',!on)}if(a==='quickSave105'){const symptoms=[...document.querySelectorAll('[data-action^="sym105:"][aria-pressed="true"]')].map(b=>b.textContent),place=$('quickPlace105').value.trim(),pain=$('quickPain105').value,note=$('quickNote105').value.trim(),when=$('quickWhen105').value;if(!when||(!symptoms.length&&!place&&pain===''&&!note)){toast('体調を一つ選ぶか、ひとこと記入してください');return}const values={};if(place)values['痛む場所']=place;if(pain!=='')values['痛みの強さ（0〜10）']=pain;const body=[symptoms.join('・'),note].filter(Boolean).join('\n');if(await mutate(n=>n.entries.push({id:uid(),kind:'diary',category:'healthquick',title:'体調メモ',when,body,values,photos:[],modified:Date.now()}))){closeModal();toast(t('saved'))}}if(a==='checkAdd105'){const title=$('checkText105').value.trim();if(!title){toast('内容を入力してください');return}if(await mutate(n=>n.entries.push({id:uid(),kind:'diary',category:id,title,body:'',when:localDT(),values:{},photos:[],done:false,modified:Date.now()}))){closeModal();checklist105(id);toast(t('saved'))}}if(a==='summaryShow105')showSummary105();if(a==='simpleSave105'){const v=$('simpleHome105').checked;await mutate(n=>n.settings.simpleHome=v,{undo:false});toast(t('saved'))}if(a==='order105'){const order=homeOrder105(),i=order.indexOf(id),j=i+Number(arg);if(j>=0&&j<order.length){[order[i],order[j]]=[order[j],order[i]];const top=window.scrollY;await mutate(n=>n.settings.homeOrder=order,{undo:false});window.scrollTo(0,top)}}if(a==='quiet105'){await mutate(n=>n.settings.quietMode=n.settings.quietMode===false,{undo:false});toast(t('saved'))}if(a==='checkTrash105'){const item=S.entries.find(x=>x.id===id);if(confirm('この項目をごみ箱へ移しますか？')){await mutate(n=>n.entries.find(x=>x.id===id).deleted=Date.now());closeModal();checklist105(item.category)}}if(a==='shake105')await setShake105();if(a==='resume105'&&conceal105){const v=conceal105;conceal105=null;const d=$('modal');d.replaceChildren(...v.nodes);d.showModal();modalSeed=v.seed;modalChanged=v.changed;editId=v.editId;editPhotos=v.photos;pendingSound=v.sound;render()}if(a==='planStatus105'){await mutate(n=>{const p=n.plans.find(x=>x.id===id);p.progress={...(p.progress||{}),[day()]:arg}});toast(t('saved'))}if(a==='planChange105')planEdit(id)}catch(err){console.error(err);toast(t('failed'))}},true);
