let memo106=null,memoOpening106=false,memoLeaving106=null,record106=null,preview106=null;
const MEMO_SECONDS106=20;
function memoStatus106(text,error=false){const e=$('recordStatus');if(e){e.textContent=text;e.classList.toggle('record-error106',error)}}
function memoButtons106(){const r=record106,stage=r?.stage||'idle',busy=['requesting','recording','processing'].includes(stage);const rec=document.querySelector('[data-action="recordStart"]'),stop=document.querySelector('[data-action="recordStop"]'),listen=document.querySelector('[data-action="recordListen106"]');if(rec)rec.disabled=busy;if(stop)stop.disabled=!['requesting','recording'].includes(stage);if(listen)listen.disabled=busy||!pendingSound;const clock=$('recordCountdown106'),meter=$('recordMeter106');if(clock)clock.textContent=stage==='recording'?`残り ${r.remaining} 秒`:stage==='requesting'?'マイクを準備中…':stage==='processing'?'録音をまとめています…':`最長 ${MEMO_SECONDS106} 秒`;if(meter)meter.value=stage==='recording'?r.remaining:MEMO_SECONDS106}
