async function saveMemo106(){const draft=memoSnapshot106(),session=memo106;if(!draft||!session)return true;if(!draft.date||!draft.time){const e=$('memoSave106');if(e)e.textContent='日付と時刻を入力してください。まだ保存できていません。';return false}if(!draft.title&&!draft.note.trim()&&!draft.sound&&!S.plans.some(p=>p.id===draft.id)){const e=$('memoSave106');if(e)e.textContent='文字か声を入れると自動保存します。';return true}const sig=JSON.stringify(draft);if(sig===session.saved)return true;const e=$('memoSave106');if(e)e.textContent='保存中…';const ok=await mutate(n=>{const i=n.plans.findIndex(p=>p.id===draft.id),old=i<0?{}:n.plans[i],p={...old,...draft,title:draft.title||(draft.sound?'音声メモ':'メモ'),enabled:old.enabled??true,progress:old.progress||{},modified:Date.now()};if(i<0)n.plans.push(p);else n.plans[i]=p},{undo:false,refresh:false});if(ok)session.saved=sig;if(memo106===session&&$('memoSave106'))$('memoSave106').textContent=ok?'✓ 自動保存しました':'保存できませんでした。この画面を閉じず、空き容量を確認してください。';return ok}
