const oldPlanEdit106=planEdit;
planEdit=async function(id){if(memoOpening106)return;memoOpening106=true;try{if(memo106){if(!await finishMemo106())return;memo106=null}const p=S.plans.find(p=>p.id===id)||{},key=p.id||uid();pendingSound=p.sound||null;record106=null;memo106={id:key,saved:null,timer:null};modal(`<h1>予定・音声メモ</h1><p>追加１件でメモ１件です。文字だけ・声だけでも残せます。</p>${field('予定名・メモの見出し','planTitle',p.title||'')}${area('メモ','planNote106',p.note||'')}${field('日付','planDate',p.date||day(),'date')}${field('時刻','planTime',p.time||localDT().slice(11,16),'time')}${select('繰り返し','planRepeat',[['once','指定日のみ'],['daily','毎日'],['weekdays','月〜金']],p.repeat||'once')}<section class="voice-panel106"><h2>声のメモ</h2><div class="voice-buttons106">${btn('● 録音','recordStart','voice-record106')}${btn('■ 停止','recordStop','voice-stop106')}${btn('▶ 聞く','recordListen106','voice-listen106')}</div><p id="recordCountdown106" class="record-clock106">最長20秒</p><progress id="recordMeter106" max="20" value="20" aria-label="録音の残り時間"></progress><p id="recordStatus" role="status" aria-live="polite">${p.sound?'録音があります。「聞く」で確認できます。':'まだ録音はありません。「録音」を押して話してください。'}</p></section><p id="memoSave106" role="status">入力内容は自動保存します。戻る・閉じるときも保存します。</p><p class="muted">時刻のお知らせは、録音があればその声、なければ上の予定名を読み上げます。自動音声の有効・停止は表示設定で選べます。</p>${btn('閉じて戻る','cancel','memo-close106')}`);if(p.id)memo106.saved=JSON.stringify(memoSnapshot106());modalSeed=formFingerprint();memoButtons106()}finally{memoOpening106=false}};
