function lcPick109(){const p=lc109().products.find(x=>x.id===lcDraft109.product);if(!p)return null;const variants=p.variants.filter(x=>lcDraft109.abv==null||x.abv===Number(lcDraft109.abv));const abvs=[...new Set(p.variants.map(x=>x.abv))];const abv=abvs.length===1?abvs[0]:lcDraft109.abv;const mls=[...new Set(variants.map(x=>x.ml))];const ml=mls.length===1?mls[0]:lcDraft109.ml;return {p,abvs,mls,abv,ml}}
