function lcChooser109(){const {products,type,makers}=lcSeedChoice109(),names=products.filter(p=>p.type===type&&p.maker===lcDraft109.maker),pick=lcPick109();return `<section class="card lc-choose109"><h2>② 飲んだお酒を選ぶ</h2>${select('種別','lcType109',[['','選んでください'],...LC_TYPES109.map(x=>[x,x])],type)}${type?select('メーカー','lcMaker109',[['','選んでください'],...makers.map(x=>[x,x])],lcDraft109.maker||''):''}${lcDraft109.maker?select('商品名','lcProduct109',[['','選んでください'],...names.map(p=>[p.id,p.name])],lcDraft109.product||''):''}${pick?(pick.abvs.length>1?select('アルコール度数','lcAbv109',[['','選んでください'],...pick.abvs.map(a=>[String(a),a+'％'])],lcDraft109.abv==null?'':String(lcDraft109.abv)):`<p>度数：<strong>${pick.abvs[0]}％</strong></p>`):''}${pick&&pick.abv!=null?(pick.mls.length>1?select('容量','lcMl109',[['','選んでください'],...pick.mls.map(n=>[String(n),n+'ml'])],lcDraft109.ml==null?'':String(lcDraft109.ml)):`<p>容量：<strong>${pick.mls[0]}ml</strong>（選択不要）</p>`):''}${pick?lcCan109(type):''}${pick&&pick.ml!=null&&pick.abv!=null?`<div class="lc-confirm109"><strong>${esc(pick.p.maker)} ${esc(pick.p.name)}</strong><p>${pick.ml}ml ／ ${pick.abv}％</p><p>１本の純アルコール量：${lcRound109(pick.ml*pick.abv/100*.8)}g</p></div>${field('飲み干した本数','lcCount109',lcDraft109.count||1,'number','min="1" max="99" step="1" inputmode="numeric"')}${btn('このお酒を飲んだ分に加える','lcAdd109','primary')}`:''}${type&&!makers.length?'<p>まだ商品がありません。下の「お酒を追加登録」から登録できます。</p>':''}<p>${btn('お酒を追加登録','lcNew109')}${btn('量をccで入力する','lcMeasure109')}</p></section>`}
function lcSession109(s){const all=s.drinks.filter(d=>!d.cancelled),total=lcTotals109(all);return `<section class="card"><h2>${s.end?'今回の合計':'飲んだ分の合計'}</h2><div class="lc-total109"><span>${lcRound109(total.ml)}<small>ml（${lcRound109(total.ml)}cc）</small></span><span>${lcRound109(total.grams)}<small>g 純アルコール</small></span></div>${s.end?`<p>終了：${esc(stampSeconds108(s.end))}</p>`:''}${s.drinks.slice().reverse().map(d=>`<article class="entry ${d.cancelled?'lc-cancelled109':''}"><strong>${esc(d.maker)} ${esc(d.name)}</strong><p>${esc(d.type)} ／ ${d.ml}ml × ${d.count}${d.measured?'回':'本'} ／ ${d.abv}％ → ${lcRound109(lcGrams109(d))}g</p><small>${esc(stampSeconds108(d.when))}</small>${d.cancelled?'<p>取り消し済み（集計対象外）</p>':btn('この登録を取り消す','lcUndo109:'+s.id+':'+d.id)}</article>`).join('')||'<p>まだ登録はありません。</p>'}</section>`}
function lcMonthRows109(month){return lc109().sessions.flatMap(s=>s.drinks.filter(d=>!d.cancelled).map(d=>({...d,sessionId:s.id}))).filter(d=>day(new Date(d.when)).startsWith(month))}
function lcMonthView109(){const rows=lcMonthRows109(lcMonth109),tot=lcTotals109(rows),by={};for(const d of rows){const v=by[d.type]||={ml:0,grams:0};v.ml+=lcMl109(d);v.grams+=lcGrams109(d)}return `<section class="card"><h2>１か月の合計・グラフ</h2>${field('表示する月','lcMonth109',lcMonth109,'month')}<p><strong>${lcRound109(tot.ml)}ml ／ 純アルコール ${lcRound109(tot.grams)}g</strong></p><div class="table-wrap"><table><thead><tr><th>酒類</th><th>飲んだ量</th><th>純アルコール</th></tr></thead><tbody>${Object.entries(by).map(([k,v])=>`<tr><th>${esc(k)}</th><td>${lcRound109(v.ml)}ml</td><td>${lcRound109(v.grams)}g</td></tr>`).join('')||'<tr><td colspan="3">記録はまだありません</td></tr>'}</tbody></table></div>${select('グラフの酒類','lcGraphType109',[['all','全酒類'],...LC_TYPES109.map(x=>[x,x])],lcTypeFilter109)}${select('縦軸','lcMetric109',[['grams','純アルコール量（g）'],['ml','飲んだ量（ml）']],lcMetric109)}${lcGraph109(rows)}<details><summary>日別の数値を開く</summary>${lcDailyTable109(rows)}</details><p class="muted">登録した日の量を表示します。未登録の日は「記録なし」です。時間経過による分解・体内残量は計算しません。</p></section>`}
function lcDays109(){const [y,m]=lcMonth109.split('-').map(Number);return new Date(y,m,0).getDate()}
function lcDaily109(rows){const out=Array.from({length:lcDays109()},()=>({ml:0,grams:0,n:0}));for(const d of rows){if(lcTypeFilter109!=='all'&&d.type!==lcTypeFilter109)continue;const n=new Date(d.when).getDate()-1;out[n].ml+=lcMl109(d);out[n].grams+=lcGrams109(d);out[n].n++}return out}
function lcGraph109(rows){const vals=lcDaily109(rows),unit=lcMetric109==='ml'?'ml':'g',max=Math.max(1,...vals.map(v=>v[lcMetric109])),w=600,h=240,left=64,top=24,bottom=200,width=510;const x=i=>left+i*width/(vals.length-1),y=v=>bottom-v/max*(bottom-top);const line=vals.map((v,i)=>`${x(i)},${y(v[lcMetric109])}`).join(' ');return `<svg viewBox="0 0 ${w} ${h}" role="img" aria-label="${esc(lcMonth109)}の日別${unit}折れ線グラフ" class="lc-chart109"><title>${esc(lcMonth109)}の日別${unit}。未登録日は白丸。</title><line x1="${left}" y1="${top}" x2="${left}" y2="${bottom}" stroke="currentColor"/><line x1="${left}" y1="${bottom}" x2="580" y2="${bottom}" stroke="currentColor"/><text x="4" y="24" font-size="16">${lcRound109(max)}${unit}</text><text x="20" y="204" font-size="16">0</text><polyline points="${line}" fill="none" stroke="#6b3589" stroke-width="3"/>${vals.map((v,i)=>`<circle cx="${x(i)}" cy="${y(v[lcMetric109])}" r="4" fill="${v.n?'#6b3589':'white'}" stroke="#6b3589"><title>${i+1}日：${v.n?lcRound109(v[lcMetric109])+unit:'記録なし'}</title></circle>${i===0||(i+1)%5===0||i===vals.length-1?`<text x="${x(i)}" y="225" text-anchor="middle" font-size="15">${i+1}</text>`:''}`).join('')}</svg>`}
function lcDailyTable109(rows){return '<table><thead><tr><th>日</th><th>量（ml）</th><th>純アルコール（g）</th></tr></thead><tbody>'+lcDaily109(rows).map((v,i)=>`<tr><th>${i+1}</th><td>${v.n?lcRound109(v.ml):'記録なし'}</td><td>${v.n?lcRound109(v.grams):'—'}</td></tr>`).join('')+'</tbody></table>'}
function lastCallView109(){const c=lc109(),s=lcActive109(),last=c.sessions.at(-1);return title('lastcall')+`<p>飲んだ種類と量を残す記録帳です。写真・外部の画像認識は使いません。</p><section class="card"><h2>① 飲む前・飲み終わり</h2><div class="lc-start109">${btn(s?'飲み始め済み':'飲み始め','lcStart109','primary')}${btn('飲み終わり','lcEnd109','primary')}</div>${s?`<p>開始：${esc(stampSeconds108(s.start))}</p><p>飲み干した缶を選んで加算してください。途中で閉じても記録は残ります。</p>`:'<p>「飲み始め」で１回分の記録を開始します。</p>'}</section>${s?lcChooser109()+lcSession109(s):last?lcSession109(last):''}${!s?`<p>${btn('お酒を追加登録','lcNew109')}${btn('以前の記録を追加','lcPast109')}</p>`:''}${lcMonthView109()}<details class="card"><summary>過去の飲酒記録</summary>${c.sessions.slice().reverse().map(s=>`<p>${btn(esc(stampSeconds108(s.start))+' ／ '+(s.end?'終了':'記録中'),'lcShow109:'+s.id)}</p>`).join('')||'<p>記録はありません。</p>'}</details><details class="card"><summary>商品候補・データについて</summary><p>初期商品はビール10商品・缶チューハイ10商品。公開調査・販売店の売れ筋掲載を参考に選んだ候補です。全国売上上位10ではありません。</p><p>確認日：2026年10月31日。商品は登録後に更新される場合があるため、手元のラベルを確認してください。銘柄ごとに登録済みの容量・度数を選びます。</p><p>容量は１缶あたりです。６缶パックは１缶の容量を選び、本数を６にします。</p><p>純アルコール量＝飲んだ量ml×度数÷100×0.8。写真は保存しません。飲酒運転の可否や酔いの判定には使えません。</p><a href="LAST_CALL_SOURCES.html" target="_blank" rel="noopener">選定資料・商品情報の出典</a></details>`}
function lcAddForm109(){const c=lc109(),type=lcDraft109.type||'缶チューハイ';modal(`<h1>お酒を追加登録</h1><p>分かる項目は候補をタッチ。ないものは自由に書けます。</p>${select('種別','lcNewType109',LC_TYPES109.map(x=>[x,x]),type)}${field('メーカー','lcNewMaker109','','text','list="lcMakers109" maxlength="120"')}${field('商品名','lcNewName109','','text','list="lcNames109" maxlength="120"')}<datalist id="lcMakers109">${[...new Set(c.products.map(x=>x.maker))].map(x=>`<option value="${esc(x)}"></option>`).join('')}</datalist><datalist id="lcNames109">${[...new Set(c.products.map(x=>x.name))].map(x=>`<option value="${esc(x)}"></option>`).join('')}</datalist><div class="lc-chip109">${[...new Set(c.products.filter(x=>x.type===type).map(x=>x.maker))].map(x=>btn(esc(x),'lcFillMaker109:'+encodeURIComponent(x))).join('')}</div>${field('アルコール度数（％）','lcNewAbv109','','number','min="0" max="100" step="0.1" inputmode="decimal"')}${lcQuickChoices109('lcNewAbv109',[0,3,4,5,6,7,9,12,15,20,25,40],'%')}${field('容量（１本あたりml）','lcNewMl109','','number','min="1" step="1" inputmode="decimal"')}${lcQuickChoices109('lcNewMl109',[180,250,350,500,700,720,750,1000,1800],'ml')}<p>手元のラベルの数字を確認してください。登録したお酒は選択一覧に加わります。</p>${modalButtons('lcNewSave109')}`);$('modal').dataset.help107='lastcall'}
function lcQuickChoices109(id,vals,unit){return `<div class="lc-chip109">${vals.map(x=>btn(x+unit,'lcValue109:'+id+':'+x)).join('')}</div>`}
function lcMeasureForm109(past=false){if(!past&&!lcActive109()){toast('先に「飲み始め」を押してください。');return}const {products}=lcSeedChoice109();modal(`<h1>${past?'以前の飲酒を記録':'飲んだ量をccで記録'}</h1><p>ウイスキー・焼酎などは、水や氷を加える前の原酒の量を入力します。１cc＝１mlです。</p>${field('飲んだ日時','lcMeasureWhen109',localDT(),'datetime-local')}${select('種別','lcMeasureType109',LC_TYPES109.map(x=>[x,x]),'ウイスキー')}${field('メーカー（不明なら「不明」）','lcMeasureMaker109','不明','text','list="lcMeasureMakers109" maxlength="120"')}${field('商品名（不明なら「不明」）','lcMeasureName109','不明','text','maxlength="120"')}<datalist id="lcMeasureMakers109">${[...new Set(products.map(x=>x.maker))].map(x=>`<option value="${esc(x)}"></option>`).join('')}</datalist>${field('飲んだ量（cc）','lcMeasureMl109','','number','min="0.1" step="0.1" inputmode="decimal"')}${lcQuickChoices109('lcMeasureMl109',[30,60,90,180,350,500],'cc')}${field('アルコール度数（％）','lcMeasureAbv109','','number','min="0" max="100" step="0.1" inputmode="decimal"')}${lcQuickChoices109('lcMeasureAbv109',[3,5,7,9,12,15,20,25,40],'%')}${modalButtons('lcMeasureSave109:'+(past?'past':'active'))}`);$('modal').dataset.help107='lastcall'}
function lcValidQuantity109(ml,abv,count=1){return Number.isFinite(ml)&&ml>0&&ml<=100000&&Number.isFinite(abv)&&abv>=0&&abv<=100&&Number.isFinite(count)&&count>0&&count<=99}
async function lcRecord109(d,past=false){if(!lcValidQuantity109(d.ml,d.abv,d.count)||!Number.isFinite(Date.parse(d.when))){toast('量・度数・日時を確認してください');return false}const id=lcActive109()?.id;if(!past&&!id){toast('先に「飲み始め」を押してください');return false}return mutate(n=>{const c=n.lastCall;if(past){c.sessions.push({id:uid(),start:d.when,end:d.when,drinks:[d]})}else{const s=c.sessions.find(s=>s.id===id&&!s.end);if(!s)throw Error('Session closed');s.drinks.push(d)}})}
const renderLast109=render;render=function(){if(page==='lastcall'){const target=page;page='home';renderLast109();page=target;document.body.classList.remove('on-home106');document.querySelector('.site-notice').hidden=true;$('creatorCredit').hidden=true;$('app').innerHTML=lastCallView109();updateHelpButtons();$('backBtn')&&($('backBtn').disabled=false);const start=document.querySelector('[data-action="lcStart109"]'),end=document.querySelector('[data-action="lcEnd109"]');if(start)start.disabled=!!lcActive109();if(end)end.disabled=!lcActive109();return}renderLast109()};
help107.lastcall=['「飲み始め」を押し、種別→メーカー→商品名→度数→容量から飲んだお酒を選びます。容量が１種類なら選択は不要です。','本数を確認して加算。「飲み終わり」で１回分を閉じます。原酒はcc入力できます。取り消し・商品追加・月別合計とグラフも使えます。'];HELP.lastcall=()=>help107.lastcall;
help107.plans=['見出しは不要です。「読み上げる内容」に選択文を入れたり、自由に追記したりします。文字は上から続けて１回読みます。','録音があればその声、ブザー・ベルを選んだ場合はその音を使います。本文を編集すると文字読み上げへ戻ります。','自動音声を有効にし、この画面を開いて使います。画面ロック中などの確実な通知はできません。'];
document.addEventListener('change',e=>{const id=e.target.id,v=e.target.value;if(id==='lcType109'){lcDraft109={type:v};render()}if(id==='lcMaker109'){lcDraft109={type:lcDraft109.type,maker:v};render()}if(id==='lcProduct109'){lcDraft109={type:lcDraft109.type,maker:lcDraft109.maker,product:v};render()}if(id==='lcAbv109'){lcDraft109.abv=v===''?null:Number(v);delete lcDraft109.ml;render()}if(id==='lcMl109'){lcDraft109.ml=v===''?null:Number(v);render()}if(id==='lcMonth109'&&/^\d{4}-\d{2}$/.test(v)){lcMonth109=v;render()}if(id==='lcGraphType109'){lcTypeFilter109=v;render()}if(id==='lcMetric109'){lcMetric109=v;render()}});
document.addEventListener('input',e=>{if(e.target.id==='lcCount109')lcDraft109.count=e.target.value;if(e.target.id==='planNote106'&&memo106&&!memo106.voiceOnly&&!['requesting','recording','processing'].includes(record106?.stage)){memo106.alarmKind='voice';pendingSound=null;record106=null;if($('alarmKind108'))$('alarmKind108').textContent='入力した文字を読み上げます。';memoButtons106()}});
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b)return;const [a,id,arg]=b.dataset.action.split(':');if(a==='readStop109'){e.preventDefault();e.stopImmediatePropagation();stopAlarmLive111();return}if(!a.startsWith('lc'))return;e.preventDefault();e.stopImmediatePropagation();if(helpMode||lcBusy109)return;try{if(a==='lcNew109'){lcAddForm109();return}if(a==='lcValue109'){if($(id))$(id).value=arg;return}if(a==='lcFillMaker109'){$('lcNewMaker109').value=decodeURIComponent(id);return}if(a==='lcMeasure109'){lcMeasureForm109();return}if(a==='lcPast109'){lcMeasureForm109(true);return}if(a==='lcShow109'){const s=lc109().sessions.find(s=>s.id===id);if(s){modal(`<h1>飲酒記録</h1>${lcSession109(s)}${btn('閉じる','cancel')}`);$('modal').dataset.help107='lastcall'}return}lcBusy109=true;b.disabled=true;
if(a==='lcStart109'){if(lcActive109())return;if(await mutate(n=>{const s={id:uid(),start:new Date().toISOString(),end:null,drinks:[]};n.lastCall.sessions.push(s);n.lastCall.activeId=s.id}))toast('飲み始めを保存しました')}
if(a==='lcEnd109'){const s=lcActive109();if(!s)return;if(await mutate(n=>{n.lastCall.sessions.find(x=>x.id===s.id).end=new Date().toISOString();n.lastCall.activeId=null}))toast('飲み終わりと合計を保存しました')}
if(a==='lcAdd109'){const pick=lcPick109(),count=Number($('lcCount109')?.value);if(!pick||pick.ml==null||pick.abv==null||!Number.isInteger(count)||!lcValidQuantity109(pick.ml,pick.abv,count)){toast('商品・度数・容量・本数を確認してください');return}const d={id:uid(),when:new Date().toISOString(),productId:pick.p.id,type:pick.p.type,maker:pick.p.maker,name:pick.p.name,ml:pick.ml,abv:Number(pick.abv),count};if(await lcRecord109(d)){lcDraft109.count=1;toast('飲んだ分を保存しました')}}
if(a==='lcUndo109'){const s=lc109().sessions.find(s=>s.id===id),d=s?.drinks.find(d=>d.id===arg);if(!d||d.cancelled)return;if(!confirm('この１件を集計から取り消しますか？'))return;if(await mutate(n=>n.lastCall.sessions.find(s=>s.id===id).drinks.find(d=>d.id===arg).cancelled=true)){if($('modal').open){$('modal').innerHTML=`<h1>飲酒記録</h1>${lcSession109(lc109().sessions.find(s=>s.id===id))}${btn('閉じる','cancel')}`}toast('取り消しました')}}
if(a==='lcNewSave109'){const type=$('lcNewType109').value,maker=$('lcNewMaker109').value.trim(),name=$('lcNewName109').value.trim(),abv=$('lcNewAbv109').value===''?NaN:Number($('lcNewAbv109').value),ml=Number($('lcNewMl109').value);if(!maker||!name||!lcValidQuantity109(ml,abv)){toast('メーカー・商品名・度数・容量を確認してください');return}let selectedId;if(await mutate(n=>{let p=n.lastCall.products.find(p=>p.type===type&&p.maker===maker&&p.name===name);if(!p){p={id:uid(),type,maker,name,variants:[],source:'利用者が手入力',checked:day()};n.lastCall.products.push(p)}if(!p.variants.some(v=>v.ml===ml&&v.abv===abv))p.variants.push({ml,abv});selectedId=p.id})){lcDraft109={type,maker,product:selectedId,abv,ml};await closeModal();render();toast('商品一覧へ追加しました')}}
if(a==='lcMeasureSave109'){const ml=Number($('lcMeasureMl109').value),abv=$('lcMeasureAbv109').value===''?NaN:Number($('lcMeasureAbv109').value),when=$('lcMeasureWhen109').value;if(!when||!lcValidQuantity109(ml,abv)){toast('量・度数・日時を入力してください');return}const d={id:uid(),when:new Date(when).toISOString(),type:$('lcMeasureType109').value,maker:$('lcMeasureMaker109').value.trim()||'不明',name:$('lcMeasureName109').value.trim()||'不明',ml,abv,count:1,measured:true};if(await lcRecord109(d,id==='past')){await closeModal();render();toast('飲んだ量を保存しました')}}
}catch(err){console.error('LAST CALL',err);toast('保存できませんでした。入力内容と空き容量を確認してください。')}finally{lcBusy109=false;if(b.isConnected)b.disabled=false}},true);

const memoButtons109=memoButtons106;memoButtons106=function(){memoButtons109();if($('planNote106'))$('planNote106').disabled=['requesting','recording','processing'].includes(record106?.stage)};
const FUWA_GUIDE110="<section class=\"card\"><h1>ふわナースの使い方</h1><p>入院中の大学生が、一日使う例です。全部の機能を覚える必要はありません。まずは「体調と測定データ」「日記帳」「ボイスメモ」の３つから始めましょう。</p><p>表紙は最初の画面です。「戻る」で１つ前へ、「表紙へ」で最初の画面へ戻れます。困ったら「説明」を押すと、その画面の使い方が出ます。説明を閉じ、説明をOFFにすると普通に操作できます。</p><p>通信量目安：１日１時間でも、保存済み画面・音源のオフライン利用は0GB／日（初回取得約0.02GB、更新・外部ページは別。実測平均なし）。</p></section>\n<section class=\"card\"><h2>朝７時：起きたら、今の体調を残す</h2><p>・表紙の「日々の記録」→「体調と測定データ」を押します。</p><p>・「体調を記録する」を押します。</p><p>・当てはまる症状を選びます。痛みは０（痛くない）～５（最も強い痛み）です。気分や睡眠など、分かる項目だけで大丈夫です。</p><p>・「体調を保存」を押し、保存できた表示を確認します。</p><p>・「戻る」で前の画面へ戻ります。</p><p>体温などの測定値があれば、「測定値とグラフ」の「データ記録・変更」から入力して保存します。新規入力の数値欄は白紙です。「タップして入力」の欄に今回測った値だけ入力します。欄の下の記入例は保存されません。空欄の項目も保存されません。日付を変えれば、昨日の記録も後から入れられます。</p></section>\n<section class=\"card\"><h2>朝８時：薬を飲んだことを記録する</h2><p>・表紙の「予定とお薬」→「お薬の記録」を選びます。</p><p>・薬名・量・単位などを、薬の説明書や病院の指示を見ながら登録します。難しければ登録は手伝ってもらってください。</p><p>・実際に飲んだ後に、該当する薬や食後のグループを選び、日時と状態を選び、内容を確認して服用を記録します。「今の日時を入れる」も使えます。新規の記録は日時・状態とも白紙です。「服用済み」を自分で押して開いたときだけ、その状態が選ばれます。</p><p>飲んだか分からないときは「飲んだか不明」を使います。アプリの記録だけで、もう一度飲むかを決めず、看護師さんなどに確認してください。残量は実物に合わせて自分で更新します。</p></section>\n<section class=\"card\"><h2>午前10時：先生に聞きたいことをメモする</h2><p>・「相談と連絡」→「先生・看護師さんに聞くこと」を押します。</p><p>・聞きたいことを短く書き、「追加して保存」を押します。</p><p>・聞けた項目にはチェックを付けます。</p><p>診察の前には「診察で見せる記録」を開き、期間と見せる項目を選びます。画面の内容を自分で確認してから見せます。日記の本文や写真は自動では入りません。</p></section>\n<section class=\"card\"><h2>昼12時：一言の日記と写真を残す</h2><p>・表紙の「日々の記録」→「日記帳」→「日記を書く」を押します。</p><p>・白い欄に「昼ごはんがおいしかった」など、好きなことを書きます。</p><p>・写真を付けたいときは写真の選択欄を押します。「ファイル・クラウドから写真を選ぶ」も使えます。</p><p>・「保存」を押し、保存できた表示を確認して戻ります。</p><p>写真を付けず、文字だけでも使えます。体調は「体調と測定データ」にまとめます。以前の日記は「編集」で直せます。「内容検索」では、覚えている言葉の一部分や日付から探せます。クラウドにある写真を選べるかは、スマホの設定によります。</p></section>\n<section class=\"card\"><h2>午後３時：書く代わりに、声でメモする</h2><p>・表紙の「予定とお薬」→「ボイスアラーム・ボイスメモ」を押します。</p><p>・「ボイスメモを録音」→「録音」を押します。初めてマイクの許可を聞かれたら「許可」を選びます。</p><p>・話し終わったら「停止」を押します。１件最長20秒です。</p><p>・自動保存できた表示を確認します。「聞く」で録った声を確認し、「戻る」を押します。</p><p>文字は何も書かなくて大丈夫です。録音した日時が秒まで自動で残ります。後で日付から探して「再生」を押せます。録音や保存に失敗した表示が出たら、保存済みと考えず、その画面の案内を確認してください。</p></section>\n<section class=\"card\"><h2>午後４時：予定を声で知らせる設定をする</h2><p>・「ボイスアラーム・ボイスメモ」→「ボイスアラームを追加」を押します。</p><p>・新しく作るときは現在の時刻が出ます。時・分のダイヤルを上下になぞって、知らせたい時刻に変えます。日付も確認してください。</p><p>・「約束の時間です」などの文を押すか、「読み上げる内容」に自由に書きます。選択した文の後にも書き足せます。</p><p>・必要なら繰り返しを選びます。入力後の「自動保存しました」を確認して戻ります。</p><p>・一覧の「アラームを有効にする（音を確認）」を押します。「試し聞き」で内容と音量を確認します。</p><p>文字は上から続けて１回読みます。録音した場合はその声、ブザー・ベルを選んだ場合はその音になります。音を止めたいときは「読み上げ・音を止める」を押します。</p><p>アラームは、このアプリを表示している間の補助機能です（他のページでも時刻を確認します）。画面をロックしたり、他のアプリへ移ったりすると、予定時刻に鳴る保証はありません。大切な予定はスマホ本体のアラームも設定してください。</p></section>\n<section class=\"card\"><h2>夕方６時：少し休む</h2><p>「ひと息・遊び」を開くと、ゲーム、クイズ、写真立て、自然音などを選べます。ゲームのヒントは各ゲーム内にあります。手鏡は表紙の看板を１秒長押しでも開けます。手鏡の「終了」を押すとカメラが止まります。</p><p>自然音は好きな季節と時間帯を選んで再生します。停止ボタンで止められます。音量と周囲への配慮を忘れずに。</p></section>\n<section class=\"card\"><h2>夜９時：一日を残して終わる</h2><p>・体調の変化があれば、「体調と測定データ」に追加します。</p><p>・「日記帳」に今日のことを一言だけでも書いて保存します。</p><p>・録音などの処理が終わり、保存できた表示を確認してから画面を閉じます。</p><p>毎日すべてを埋めなくても大丈夫です。残したいことだけ、無理のない範囲で使ってください。</p></section>\n<section class=\"card\"><h2>大切な記録を守る</h2><p>・ときどき「バックアップ・機種変更」を開きます。</p><p>・「バックアップを書き出す」を押します。</p><p>・保存できたファイルを、スマホ以外の自分の保管先にも残します。難しければ、信頼できる人に保存を手伝ってもらってください。</p><p>スマホを替えても、記録は自動では引き継がれません。新しいスマホでバックアップを読み込み、記録を確認するまで、古いスマホの記録を消さないでください。バックアップには日記・写真・録音などが入るので、渡す相手に注意してください。</p><p>「ごみ箱へ」に移したものは、ごみ箱から戻せます。「完全削除」は取り消せません。ブラウザーのデータ削除は、アプリ内の記録を失う原因になります。</p></section>\n<section class=\"card\"><h2>その他：LAST CALL</h2><p>飲酒記録は「LAST CALL」を開くと、見出しのすぐ下に操作手順が表示されます。商品・度数・量を自分で確認して記録する機能です。</p></section>\n<section class=\"card\"><h2>クイズとゲーム</h2><p>「クイズ150」は、文章の問題を読んで回答する遊びです。簡単・普通・難しいに各50問。各コースは、考えてから答えを開く33問・二択9問・四択8問が混ざります。自己確認式は頭の中で考え、「考えたら、答えを読む」を押します。答え本文は30文字以内で、理由は別の「理由・解説を読む」を開いて確認します。「前の問題」で戻っても確認状態は残ります。同じコース内の一巡までは重複せず、長めの推理短編も時々出ます。</p><p>「ゲーム50」は、盤面やカードを操作して遊びます。絵合わせ、記憶、消灯、スライド、迷路、箱運び、水路、文字札、配置、仕分け、川渡り、リバーシなど50種類です。ゲーム内の「遊び方」を読み、「一手戻る」「戻した手を進める」「ヒント」を使えます。ヒントは操作する場所を文章と枠で示します。必ず最善手とは限りません。「最初の盤面へ」で今回の初期状態からやり直せます。「解き方の例」では、あなたの盤面を変えずに練習用の手順を一手ずつ進めたり、完成形を見たりできます。対戦ゲームの例は一つの対局例で、勝ちを保証する手順ではありません。「ゲーム一覧へ戻る」で選び直せます。制限時間はありません。</p><p>記憶・消灯などは再配置されます。迷路や川渡りなど、同じ盤面をやり直すゲームもあります。ゲームの途中経過は生活記録として保存されず、ページを再読み込みすると最初からです。</p></section>\n<section class=\"card\"><h2>追加：アラームの期限</h2><p>１回だけのアラームは、設定時刻の24時間後に一覧から削除し、ごみ箱へ移動します。閉じている間に期限が来た場合は、次に開いた時に処理します。繰り返しと録音メモはこの自動削除の対象外です。時刻を５分以上過ぎてから復帰したアラームは、遅れて鳴らさない仕様です。</p></section>\n<section class=\"card\"><h2>読み上げる内容の入力欄</h2><p>ボイスアラームの「読み上げる内容」は、約30文字が見える小さな欄にしました。これは文字数の上限ではありません。長い文も入力でき、欄の中を上下に動かして確認できます。自動保存と、全文を続けて読む動作はそのままです。</p></section>\n<section class=\"card\"><h2>新しい表紙と画面</h2><p>表紙には「日々の記録」「予定とお薬」「相談と連絡」「ひと息・遊び」「設定と管理」の５分類があります。分類を押すと中の機能ボタンが開きます。同じ分類をもう一度押すと閉じます。複数の分類を開くこともできます。</p><p>見出し・説明・入力欄・操作ボタンを、葡萄色と生成りの共通デザインに整えました。説明は「？」、表紙へ戻る操作は淡い金色の「表紙へ」を使います。下部の「保存とご利用について」を押すと、記録の保存に関する説明が開きます。</p><p>表示設定の「暗い画面」「文字を大きく」は引き続き使えます。表紙の機能の並び順は、各分類の中で反映します。看板を１秒長押しする手鏡も引き続き使えます。</p></section>\n<section class=\"card\"><h2>女性用の記録</h2><p>「記録」「表示」を選びます。「記録」では今日の日付が最初に表示されます。「入力する項目を選ぶ」で必要な項目を選べます。必要なら日付を変え、項目や備考を入力して「この内容を記録する」を押します。入力しただけでは保存されません。</p><p>「表示」では月別の一覧表を開きます。表示月は「2026年11月」のように年と月が欠けずに出ます。その下の年・月を別々に選ぶか、左右の矢印で変更できます。一覧表のマスを押すと、その日の記録を確認・編集できます。過去の記録を消して作り直す必要はありません。</p></section>\n<section class=\"card\"><h2>日記帳で過去の記録を探す</h2><p>独立した通信量・カレンダー年表のメニューは削除しました。記録や写真そのものは削除していません。</p><p>日記帳の「日記を探す」で、開始日・終了日、言葉、写真の有無を指定します。「この条件で探す」を押すと、日記だけを絞り込めます。「条件をクリア」で一覧に戻ります。体調なども含めて探すときは「全記録を検索」を使います。</p></section>\n<section class=\"card\"><h2>５分類から機能を開く</h2></section>\n<section class=\"card\"><h2>日々の記録：日記帳、体調と測定データ、女性用の記録、飲酒記録。</h2></section>\n<section class=\"card\"><h2>予定とお薬：ボイスアラーム・ボイスメモ、お薬の記録。</h2></section>\n<section class=\"card\"><h2>相談と連絡：先生への質問、診察用まとめ、電話帳。</h2></section>\n<section class=\"card\"><h2>ひと息・遊び：ゲーム、クイズ、占い、写真立て、自然音。</h2><p>設定と管理：内容検索、持主情報、バックアップ、ごみ箱、表示設定、使い方。</p><p>持主情報のボタンを押すと、登録内容や表示の切替、編集ボタンが出ます。看板を１秒長押しする手鏡は引き続き使えます。旧「すべての機能」と「かんたん表示」の切替は廃止しました。</p></section>\n<section class=\"card\"><h2>新規入力と過去の編集</h2><p>新規入力には別の日の測定値を補充しません。過去の記録の「編集」を開くと、その記録だけの内容が表示され、保存すると同じ記録を更新します。別の新規記録は作りません。空欄に戻した測定項目は、その記録から外れます。</p><p>「家族への依頼」の機能とボタンは撤去しました。以前に保存した記録は消さず、「設定と管理」→「内容検索」から確認できます。</p></section>\n<section class=\"card\"><h2>戻る操作</h2><p>使い方や機能の画面には「戻る」を用意しました。表紙の最上位には前画面がないため付けません。５分類はその場で開閉するため別の戻る画面を作りません。写真・手鏡は既存の戻る・終了ボタンを使います。</p></section>\n<section class=\"card\"><h2>電話帳</h2><p>「相談と連絡」→「電話帳」で、各行の「編集」を押すと登録・修正できます。横へスライドすると、発信前の確認へ進みます。</p></section>";
// v1.10: editable alarm clock, full-screen memo editor, consistent navigation, guide.
function clockParts110(value){const m=/^(\d{2}):(\d{2})$/.exec(value||'');return m?[m[1],m[2]]:localDT().slice(11,16).split(':')}
function alarmClock110(value){const [h,m]=clockParts110(value);return `<section class="alarm-clock110" role="group" aria-label="アラームの時刻"><h2>知らせる時刻</h2><div class="clock-row110">${select('時','alarmHour110',Array.from({length:24},(_,i)=>{const n=String(i).padStart(2,'0');return [n,n+'時']}),h)}<span aria-hidden="true">：</span>${select('分','alarmMinute110',Array.from({length:60},(_,i)=>{const n=String(i).padStart(2,'0');return [n,n+'分']}),m)}</div><p id="clockDisplay110" aria-live="polite">設定時刻：${h}：${m}</p>${btn('現在の日付・時刻に合わせる','alarmNow110')}<p>「時」「分」をタッチして変更します。日付も確認してください。</p></section>`}
function unifyModalNav110(){const d=$('modal');if(!d.open||memoOpening106)return;const tools=d.querySelector('.modal-tools');if(tools){const backs=[...tools.querySelectorAll('[data-action="pageBack"]')];backs.slice(1).forEach(b=>b.remove());if(backs[0]){backs[0].textContent='‹ 戻る';backs[0].classList.add('nav-back110')}tools.querySelectorAll('[data-action="cancel"],[data-action="goTop"]').forEach(b=>b.remove());const homes=[...tools.querySelectorAll('[data-action="cover105"]')];homes.slice(1).forEach(b=>b.remove());if(homes[0])homes[0].textContent='⌂ 表紙へ';}
const exits=[...d.querySelectorAll('[data-action="cancel"]')];if(!tools){exits.slice(1).forEach(b=>b.remove());if(exits[0]){exits[0].textContent='‹ 戻る';exits[0].classList.add('nav-back110')}return}if(!modalTrail.length){exits.forEach(b=>b.remove())}else{exits.slice(1).forEach(b=>b.remove());if(exits[0]){exits[0].textContent='編集を閉じて一覧へ';exits[0].classList.add('nav-back110')}}
}
