const planEditor110=planEdit;planEdit=async function(id,voiceOnly=false){await planEditor110(id,voiceOnly);if(!memo106||!$('planTime'))return;const d=$('modal'),old=S.plans.find(p=>p.id===id);d.classList.add('alarm-full110');if(!memo106.voiceOnly){if(!old){$('planDate').value=day();$('planTime').value=localDT().slice(11,16)}const label=$('planTime').closest('label');label.hidden=true;$('planTime').type='hidden';label.insertAdjacentHTML('afterend',alarmClock110($('planTime').value));modalSeed=formFingerprint()}unifyModalNav110();d.scrollTop=0};
async function syncAlarmClock110(){if(!memo106||memo106.voiceOnly||!$('alarmHour110')||!$('alarmMinute110'))return false;const h=$('alarmHour110').value,m=$('alarmMinute110').value;if(!/^(?:[01]\d|2[0-3])$/.test(h)||!/^[0-5]\d$/.test(m))return false;$('planTime').value=h+':'+m;$('clockDisplay110').textContent='設定時刻：'+h+'：'+m;clearTimeout(memo106.timer);return saveMemo106()}
const lastCallView110=lastCallView109;lastCallView109=function(){return lastCallView110().replace(title('lastcall'),title('lastcall')+`<section class="lc-how110" aria-label="LAST CALLの使い方"><h2>初めての使い方</h2><ol><li><strong>「飲み始め」</strong>を押して、今回の記録を始めます。</li><li><strong>種別→メーカー→商品名→度数→容量</strong>を選びます。容量が１種類なら選択は不要です。</li><li>飲み干した本数を確認し、<strong>「このお酒を飲んだ分に加える」</strong>を押します。選ぶだけでは加算されません。</li><li>ウイスキーなどは<strong>「量をccで入力する」</strong>で、水や氷を加える前の原酒の量と度数を入れます。</li><li>最後に<strong>「飲み終わり」</strong>を押すと、今回の合計が残ります。</li></ol><p>間違えた登録は「この登録を取り消す」で取り消せます。下で月を選ぶと、酒類別合計と日別グラフが見られます。</p><p>お酒が見つからないときは「お酒を追加登録」。過去の分は「以前の記録を追加」を使います。写真・有料の画像認識は不要です。</p></section>`)};
