help107.plans=['新規アラームは現在時刻から始まります。「時」「分」をタッチして知らせたい時刻に変え、日付も確認します。','「読み上げる内容」に選択文や自由な文章を入れます。入力後は自動保存。保存表示を確認して「戻る」を押します。','時刻の通知には自動音声の有効化とアラーム一覧の表示が必要です。ロック中などの確実な通知はできません。'];
document.addEventListener('change',e=>{if(['alarmHour110','alarmMinute110'].includes(e.target.id))syncAlarmClock110()});
document.addEventListener('click',async e=>{if(e.target.closest('[data-action]')?.dataset.action!=='alarmNow110')return;e.preventDefault();e.stopImmediatePropagation();if(helpMode||!memo106)return;const now=localDT();$('planDate').value=now.slice(0,10);$('alarmHour110').value=now.slice(11,13);$('alarmMinute110').value=now.slice(14,16);await syncAlarmClock110()},true);

// Alarm scheduling: all visible app pages, bounded catch-up, success-only delivery records.
const ALARM_EXPIRY111=24*60*60*1000,ALARM_GRACE111=5*60*1000;
let alarmTickBusy111=false,alarmCleanupBusy111=false,alarmLive111=null,alarmContext111=null,alarmRetry111=new Map(),alarmIssue111='';
function alarmDue111(p,now=Date.now()){if(!p||p.voiceOnly||p.deleted||!p.enabled)return null;const t=/^(\d{2}):(\d{2})$/.exec(p.time||'');if(!t)return null;if(p.repeat==='once'){const due=new Date(p.date+'T'+p.time+':00').getTime();return Number.isFinite(due)?{time:due,key:p.date}:null}const d=new Date(now);d.setHours(+t[1],+t[2],0,0);if(d.getTime()>now)d.setDate(d.getDate()-1);if(p.repeat==='weekdays')while([0,6].includes(d.getDay()))d.setDate(d.getDate()-1);if(!['daily','weekdays'].includes(p.repeat))return null;return {time:d.getTime(),key:day(d)}}
async function expireAlarms111(now=Date.now()){if(!S||memo106||alarmCleanupBusy111)return;const ids=S.plans.filter(p=>!p.voiceOnly&&!p.deleted&&p.repeat==='once').filter(p=>{const t=new Date(p.date+'T'+p.time+':00').getTime();return Number.isFinite(t)&&now>=t+ALARM_EXPIRY111}).map(p=>p.id);if(!ids.length)return;alarmCleanupBusy111=true;try{await mutate(n=>{for(const p of n.plans)if(ids.includes(p.id)){p.deleted=now;p.expiredAt111=now}},{undo:false,refresh:false});if(page==='plans'&&!$('modal').open)render()}finally{alarmCleanupBusy111=false}}
function alarmNewest111(a,b){return (b.modified||Date.parse(b.createdAt)||0)-(a.modified||Date.parse(a.createdAt)||0)}
function statusAlarm111(){const text=alarmIssue111||(S.settings.quietMode===false?'自動通知：有効。アプリを表示中は、他のページでも時刻を確認します。':'自動通知：停止中です。「アラームを有効にする（音を確認）」を押してください。');for(const id of ['alarmStatus111','alarmInline111'])if($(id))$(id).textContent=text;if(alarmIssue111&&$('modal').open&&!$('alarmInline111'))$('modal').querySelector('.modal-tools')?.insertAdjacentHTML('afterend','<p id="alarmInline111" role="status" class="notice">'+esc(text)+'</p>')}
function unlockAlarm111(){const C=window.AudioContext||window.webkitAudioContext;try{if(C){if(!alarmContext111||alarmContext111.state==='closed')alarmContext111=new C();alarmContext111.resume?.().catch(()=>{});const o=alarmContext111.createOscillator(),g=alarmContext111.createGain();g.gain.value=0;o.connect(g).connect(alarmContext111.destination);o.start();o.stop(alarmContext111.currentTime+.02)}}catch{}if(window.speechSynthesis?.paused)speechSynthesis.resume()}
function stopAlarmLive111(){const x=alarmLive111;alarmLive111=null;if(x){clearTimeout(x.timeout);clearTimeout(x.limit);x.audio?.pause();x.nodes?.forEach(n=>{try{n.stop()}catch{}});x.finish?.(false)}stopReading109();stopAlarm108();stopPreview106()}
function failAlarm111(message){alarmIssue111=message;statusAlarm111();toast(message)}
function playAutomatic111(p,onStart){stopAlarmLive111();return new Promise(resolve=>{const run={nodes:[],started:false,finish(ok){if(alarmLive111!==run&&run.ended)return;run.ended=true;clearTimeout(run.timeout);clearTimeout(run.limit);if(alarmLive111===run)alarmLive111=null;resolve(ok)}};alarmLive111=run;const start=()=>{if(run.started||run.ended||alarmLive111!==run)return;run.started=true;clearTimeout(run.timeout);alarmIssue111='';statusAlarm111();onStart?.();};run.timeout=setTimeout(()=>{if(!run.started){run.audio?.pause();run.finish(false);failAlarm111('音の開始を確認できません。「アラームを有効にする（音を確認）」を押してください。')}},8000);
try{if(p.sound){const a=run.audio=new Audio(p.sound);a.onplaying=start;a.onended=()=>run.finish(true);a.onerror=()=>run.finish(false);a.play().then(start).catch(()=>{run.finish(false);failAlarm111('自動再生が許可されていません。「アラームを有効にする（音を確認）」を押してください。')});run.limit=setTimeout(()=>{a.pause();run.finish(run.started)},30000);return}
if(['buzzer','bell'].includes(p.alarmKind)){const C=window.AudioContext||window.webkitAudioContext;if(!C)throw Error('音を出す機能がありません');if(!alarmContext111||alarmContext111.state==='closed')alarmContext111=new C();const ctx=alarmContext111;Promise.resolve(ctx.resume?.()).then(()=>{if(alarmLive111!==run)return;if(ctx.state==='suspended'){run.finish(false);failAlarm111('音が停止状態です。「アラームを有効にする（音を確認）」を押してください。');return}const master=ctx.createGain();master.gain.value=.3;master.connect(ctx.destination);const at=ctx.currentTime;for(let i=0;i<7;i++){const o=ctx.createOscillator(),g=ctx.createGain();o.type=p.alarmKind==='buzzer'?'sawtooth':'sine';o.frequency.value=p.alarmKind==='buzzer'?220:880;g.gain.setValueAtTime(.5,at+i*.6);g.gain.exponentialRampToValueAtTime(.001,at+i*.6+.48);o.connect(g).connect(master);o.start(at+i*.6);o.stop(at+i*.6+.5);run.nodes.push(o)}start();run.limit=setTimeout(()=>run.finish(true),4400)}).catch(()=>run.finish(false));return}
if(!window.speechSynthesis||typeof SpeechSynthesisUtterance==='undefined')throw Error('読み上げ機能がありません');const text=p.note||p.title||'',chunks=text.match(/[^。！？\n]{1,100}[。！？\n]?|[。！？\n]/g)||[];if(!chunks.length)throw Error('読み上げる内容が空です');const next=()=>{if(alarmLive111!==run)return;if(!chunks.length){run.finish(true);return}const u=new SpeechSynthesisUtterance(chunks.shift());u.lang={ja:'ja-JP',en:'en-US',fr:'fr-FR'}[lang];u.onstart=start;u.onend=()=>{start();next()};u.onerror=()=>{if(run.ended)return;run.finish(false);failAlarm111('自動読み上げを開始できません。画面の「音を確認」を押してください。')};speechSynthesis.speak(u)};next();
}catch(e){run.finish(false);failAlarm111('アラームを鳴らせません：'+e.message)}})}
tickPlans=async function(now=Date.now()){if(!S||alarmTickBusy111)return;alarmTickBusy111=true;try{await expireAlarms111(now);if(document.visibilityState!=='visible'||S.settings.quietMode!==false||['requesting','recording','processing'].includes(record106?.stage)||alarmLive111)return;for(const p of S.plans){const due=alarmDue111(p,now);if(!due||now<due.time||now-due.time>ALARM_GRACE111||p.lastAlert===due.key||['done','cancelled'].includes(p.progress?.[due.key]))continue;const key=p.id+':'+due.key;if(planShown.has(key))continue;if(now-(alarmRetry111.get(key)||0)<10000)continue;alarmRetry111.set(key,now);await playAutomatic111(p,()=>{planShown.add(key);mutate(n=>{const saved=n.plans.find(x=>x.id===p.id);if(saved&&!saved.deleted)saved.lastAlert=due.key},{undo:false,refresh:false});toast(p.title||'アラーム');});if(document.visibilityState!=='visible')break;}}finally{alarmTickBusy111=false}};
function alarmSignature111(p){return p?JSON.stringify([p.date,p.time,p.repeat,p.note,p.sound,p.alarmKind,p.enabled]):''}
const saveMemo111=saveMemo106;saveMemo106=async function(){const active=memo106,id=active?.id,before=alarmSignature111(S.plans.find(p=>p.id===id)),ok=await saveMemo111();if(ok&&active&&!active.voiceOnly&&S.plans.some(p=>p.id===id)){const changed=before!==alarmSignature111(S.plans.find(p=>p.id===id));await mutate(n=>{n.settings.quietMode=false;const p=n.plans.find(p=>p.id===id);if(changed&&p){delete p.lastAlert;if(p.progress)delete p.progress[day()]}},{undo:false,refresh:false});if(changed){for(const k of planShown)if(k.startsWith(id+':'))planShown.delete(k);for(const k of alarmRetry111.keys())if(k.startsWith(id+':'))alarmRetry111.delete(k)}statusAlarm111()}return ok};
const editAlarm111=planEdit;planEdit=async function(id,voiceOnly=false){unlockAlarm111();await editAlarm111(id,voiceOnly);if(memo106&&!memo106.voiceOnly){$('modal').querySelector('h1').insertAdjacentHTML('afterend','<p id="alarmInline111" role="status"></p><p class="notice">１回だけのアラームは、設定時刻の24時間後に一覧から自動削除し、ごみ箱へ移します。繰り返しとボイスメモは対象外です。</p>');statusAlarm111()}};
const plansView111=plansView;plansView=function(){let html=plansView111();html=html.replace(title('plans'),title('plans')+`<section class="alarm-status111"><p id="alarmStatus111">${esc(alarmIssue111||'新しい登録・変更が上に表示されます。最初に音を確認してください。')}</p>${btn('アラームを有効にする（音を確認）','alarmArm111','primary')}${btn('音を止める','alarmStop111')}<p>１回だけのアラームは設定時刻の24時間後に一覧から自動削除（ごみ箱に保存）。閉じていた間に期限が来た場合は、次に開いた時に処理します。繰り返しとボイスメモは削除しません。</p><p>短い停止からの復帰は５分以内まで通知します。画面ロック中・終了中の確実な通知はできません。</p></section>`);return html};
// A dial exposes only the previous/current/next values, not a long choice list.
function wheel111(id,value,max,label){const v=Number(value)||0,prev=(v+max)%(max+1),next=(v+1)%(max+1);return `<div class="time-dial111"><label>${label}<input type="hidden" id="${id}" value="${String(v).padStart(2,'0')}"></label>${btn('▲','wheelStep111:'+id+':-1')}<div class="wheel111" data-wheel111="${id}" data-max111="${max}" role="spinbutton" tabindex="0" aria-label="${label}のダイヤル" aria-valuemin="0" aria-valuemax="${max}" aria-valuenow="${v}"><span class="wheel-prev111">${String(prev).padStart(2,'0')}</span><strong>${String(v).padStart(2,'0')}</strong><span class="wheel-next111">${String(next).padStart(2,'0')}</span></div>${btn('▼','wheelStep111:'+id+':1')}</div>`}
alarmClock110=function(value){const [h,m]=clockParts110(value);return `<section class="alarm-clock110"><h2>知らせる時刻</h2><div class="clock-row110">${wheel111('alarmHour110',h,23,'時')}<span>：</span>${wheel111('alarmMinute110',m,59,'分')}</div><p id="clockDisplay110">設定時刻：${h}：${m}</p>${btn('現在の日付・時刻に合わせる','alarmNow110')}<p>数字を上下になぞるか、▲▼を押して合わせます。キーボードの上下矢印でも変更できます。</p></section>`};
function paintWheel111(id){const w=document.querySelector('[data-wheel111="'+id+'"]'),input=$(id);if(!w||!input)return;const max=+w.dataset.max111,v=+input.value;w.querySelector('strong').textContent=String(v).padStart(2,'0');w.querySelector('.wheel-prev111').textContent=String((v+max)%(max+1)).padStart(2,'0');w.querySelector('.wheel-next111').textContent=String((v+1)%(max+1)).padStart(2,'0');w.setAttribute('aria-valuenow',String(v))}
function stepWheel111(id,delta,save=true){const max=id==='alarmHour110'?23:59,el=$(id);if(!el)return;el.value=String((+el.value+delta%(max+1)+max+1)%(max+1)).padStart(2,'0');paintWheel111(id);if(save)syncAlarmClock110()}
let wheelDrag111=null;
document.addEventListener('pointerdown',e=>{const w=e.target.closest('.wheel111');if(!w||helpMode)return;e.preventDefault();wheelDrag111={id:w.dataset.wheel111,y:e.clientY,start:+$(w.dataset.wheel111).value,max:+w.dataset.max111};w.setPointerCapture?.(e.pointerId)});
document.addEventListener('pointermove',e=>{if(!wheelDrag111)return;e.preventDefault();const d=wheelDrag111,steps=Math.trunc((d.y-e.clientY)/24);$(d.id).value=String(((d.start+steps)%(d.max+1)+d.max+1)%(d.max+1)).padStart(2,'0');paintWheel111(d.id)},{passive:false});
function finishWheel111(){if(wheelDrag111){wheelDrag111=null;syncAlarmClock110()}}
document.addEventListener('pointerup',finishWheel111);document.addEventListener('pointercancel',finishWheel111);
document.addEventListener('wheel',e=>{const w=e.target.closest('.wheel111');if(!w||helpMode)return;e.preventDefault();stepWheel111(w.dataset.wheel111,e.deltaY>0?1:-1)},{passive:false});
document.addEventListener('keydown',e=>{const w=e.target.closest('.wheel111');if(!w||!['ArrowUp','ArrowDown'].includes(e.key)||helpMode)return;e.preventDefault();stepWheel111(w.dataset.wheel111,e.key==='ArrowUp'?-1:1)});
document.addEventListener('click',async e=>{const a=e.target.closest('[data-action]')?.dataset.action;if(!a)return;const [key,id,delta]=a.split(':');if(!['alarmArm111','alarmStop111','wheelStep111'].includes(key))return;e.preventDefault();e.stopImmediatePropagation();if(helpMode)return;if(key==='wheelStep111')stepWheel111(id,+delta);if(key==='alarmStop111')stopAlarmLive111();if(key==='alarmArm111'){unlockAlarm111();await mutate(n=>n.settings.quietMode=false,{undo:false,refresh:false});alarmIssue111='';statusAlarm111();await playAutomatic111({title:'アラームを有効にしました。',note:'アラームを有効にしました。',alarmKind:'voice'},()=>{});}},true);
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible')tickPlans()});window.addEventListener('focus',()=>tickPlans());

