async function saveWomen115(){
 if(womenSaving115||!womenDraft115)return;womenDraftRead115();const d=womenDraft115,date=d.date;
 const valid=/^\d{4}-\d{2}-\d{2}$/.test(date)&&day(new Date(date+'T12:00:00'))===date;
 const fail=text=>{const el=$('womenError115');if(el)el.textContent=text;toast(text)};
 if(!valid){fail('日付を確認してください。');return}
 if(!Object.values(d.values).some(v=>v!==''&&v!=null)&&!d.note.trim()){fail('記録する項目か備考を入力してください。');return}
 for(const [key,v]of Object.entries(d.values)){if(v===''||v==null)continue;const w=W.find(w=>w[0]===key),num=W_NUMBERS[key];if(!w){fail('項目を確認してください。');return}if(num){const value=Number(v);if(!Number.isFinite(value)||value<0||value>num.max||Math.abs(value/num.step-Math.round(value/num.step))>.00001){fail('数値の範囲を確認してください。');return}}else if(!w[2].some(x=>String(x[0])===String(v))){fail('選択項目を確認してください。');return}}
 womenSaving115=true;const b=document.querySelector('[data-action="women115:save"]');if(b)b.disabled=true;
 try{const entry={id:uid(),kind:'women',when:date+'T'+localDT().slice(11),title:t('women'),body:d.note,values:Object.fromEntries(Object.entries(d.values).filter(([,v])=>v!==''&&v!=null)),photos:[]};const ok=await mutate(n=>n.entries.push(entry),{refresh:false});if(ok){womenDraft115=null;womenMode115='display';womenMonth=date.slice(0,7);render();toast(t('saved'))}else fail('保存できませんでした。入力はそのまま残しています。')}finally{womenSaving115=false;if(b?.isConnected)b.disabled=false}
}
document.addEventListener('click',e=>{const a=e.target.closest('[data-action]')?.dataset.action;if(!a?.startsWith('women115:'))return;e.preventDefault();e.stopImmediatePropagation();if(helpMode)return;const cmd=a.split(':')[1];if(cmd==='save'){saveWomen115();return}if(womenMode115==='record')womenDraftRead115();if(cmd==='record'){womenMode115='record';womenDraft115??={date:day(),values:{},note:''}}if(cmd==='display')womenMode115='display';render()},true);
document.addEventListener('submit',e=>{if(e.target.id==='womenForm115'){e.preventDefault();saveWomen115()}},true);
for(const event of ['input','change'])document.addEventListener(event,e=>{if(womenMode115==='record'&&e.target.closest?.('#womenForm115'))womenDraftRead115()});
document.addEventListener('change',e=>{if(!['womenYear115','womenMon115'].includes(e.target.id))return;const y=Number($('womenYear115').value),m=Number($('womenMon115').value);if(Number.isInteger(y)&&y>=1&&y<=9999&&m>=1&&m<=12){womenMonth=String(y).padStart(4,'0')+'-'+String(m).padStart(2,'0');render()}});
