function possibleMoves118(s){
 const cells=n=>Array.from({length:n},(_,i)=>['cell',i]);
 switch(s.type){
 case'sequence':return s.preview?[['begin','']]:[['cell',s.sequence[s.progress]]];
 case'locations':return s.preview?[['begin','']]:[['cell',s.cards.indexOf(s.order[s.progress])]];
 case'memory':{const wanted=s.open.length<s.group&&s.open.length?s.cards[s.open[0]]:null;return cells(s.cards.length).filter(([,i])=>!s.matched.includes(i)&&!s.open.includes(i)).sort((a,b)=>Number(s.cards[b[1]]===wanted)-Number(s.cards[a[1]]===wanted))}
 case'slide':return PLAY115.neighbors(s.cells.indexOf(-1),3).map(i=>['cell',i]);
 case'rotate':return [...(s.axis!=='col'?[0,1,2].map(i=>['row',i]):[]),...(s.axis!=='row'?[0,1,2].map(i=>['col',i]):[])];
 case'maze':case'soko':return ['up','right','down','left'].map(x=>['dir',x]);
 case'chain':return cells(s.words.length).filter(([,i])=>!s.path.includes(i)&&(!s.path.length||s.words[s.path.at(-1)].at(-1)===s.words[i][0]));
 case'wordPath':return cells(s.cells.length).filter(([,i])=>!s.path.includes(i)&&s.cells[i]===[...s.word][s.path.length]&&(!s.path.length||PLAY115.adjacent(s.path.at(-1),i,s.n)));
 case'symmetry':return cells(s.cells.length).filter(([,i])=>s.cells[i]!==s.target[i]);
 case'flow':{const k=s.paths.findIndex((p,i)=>p.at(-1)!==s.pairs[i][1]);if(k<0)return[];if(s.color!==k)return[['color',k]];const path=s.paths[k],start=s.pairs[k][0],end=s.pairs[k][1];if(path.some((v,i)=>v!==start+i))return[['cell',start]];return [['cell',Math.min(end,path.at(-1)+1)]]}
 case'sort':{const out=[];for(let i=0;i<3;i++)if(s.tubes[i].length)for(let j=0;j<3;j++)if(i!==j&&s.tubes[j].length<s.cap&&(!s.tubes[j].length||s.tubes[j].at(-1)===s.tubes[i].at(-1)))out.push(['cell',s.selected===null?i:s.selected===i?j:s.selected]);return out}
 case'hanoi':{const out=[];for(let i=0;i<3;i++)if(s.towers[i].length)for(let j=0;j<3;j++)if(i!==j&&(!s.towers[j].length||s.towers[j].at(-1)>s.towers[i].at(-1)))out.push(['cell',s.selected===null?i:s.selected===i?j:s.selected]);return out}
 case'river':return [0,1,2,3].map(i=>['boat',i]);
 case'reversi':return cells(s.cells.length).filter(([,i])=>PLAY115.flips(s,i,1).length);
 case'connect':return cells(4);
 case'tray':return cells(s.cards.length);
 case'link':if(s.selected!==null){const j=s.cells.findIndex((v,j)=>PLAY115.linkable(s,s.selected,j));return [['cell',j<0?s.selected:j]]}else{for(let i=0;i<s.cells.length;i++)for(let j=i+1;j<s.cells.length;j++)if(PLAY115.linkable(s,i,j))return [['cell',i]];return[]}
 case'match':{for(let i=0;i<s.cells.length;i++)for(const j of PLAY115.neighbors(i,s.n))if(PLAY115.matchMove(s,i,j).length)return [['cell',s.selected===null?i:s.selected===i?j:s.selected]];return[]}
 case'mines':if(s.flagMode)return [['flag','']];return cells(25).filter(([,i])=>!s.mines.includes(i)&&!s.opened.includes(i)&&!s.flags.includes(i));
 case'unblock':if(s.selected===null)return s.cars.flatMap((car,i)=>{const t=structuredClone(s);t.selected=i;return ['up','right','down','left'].some(d=>{const x=structuredClone(t);return PLAY115.move(x,'dir',d)})?[['cell',i]]:[]});return ['up','right','down','left'].map(d=>['dir',d]);
 default:return cells(s.cells?.length||s.n*s.n);
 }
}
